-- =============================================================================
-- 444 — LE CAHIER D'EXERCICES DE TLE (partie 9)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/Tle/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 444 --niveau Tle --matieres philosophie,sport --suffixe 9 > supabase/contenu/444_exercices_tle_9.sql
--
-- 87 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   philosophie.k181        30 exercices · 10 chapitres
--   philosophie.k182        27 exercices · 9 chapitres
--   sport.k198              30 exercices · 10 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('8df57df5-b863-5c0d-9e7c-13b2f0214ddc'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le doute qui ne peut pas douter","competence":"analyser-texte","situation":"Pour ton oral, tu relis le passage où Descartes cherche une vérité que rien ne puisse ébranler. Repère les mots clés, remets les étapes dans l’ordre, puis juge la méthode.","documents":[{"id":"desc","type":"texte","genre":"source","titre":"Le point fixe","blocs":["Je peux mettre en question mes sens, le monde et jusqu’à mon corps. Mais celui qui doute pense ; et celui qui pense existe nécessairement. Cette vérité-là est si ferme que les suppositions les plus extravagantes ne peuvent l’ébranler."],"source":"D’après Descartes, *Discours de la méthode* (1637) — texte adapté"}],"questions":[{"enonce":"Touche les deux verbes qui montrent que le doute est déjà une pensée.","aide":"Un verbe dit l’acte de mettre en question ; l’autre, ce que fait celui qui l’accomplit.","type":"zone","document":"desc","multiple":true},{"enonce":"Remets dans l’ordre le raisonnement du texte.","aide":"On part du doute et on arrive à la certitude.","type":"ordre","items":[{"id":"a","texte":"Et celui qui pense existe nécessairement"},{"id":"b","texte":"Je mets en question mes sens, le monde et mon corps"},{"id":"c","texte":"Mais celui qui doute est en train de penser"},{"id":"d","texte":"J’ai trouvé une vérité que le doute ne peut pas ébranler"}]},{"enonce":"Que fait Descartes de son doute ?","aide":"Le doute est un moyen, pas un but.","type":"choix","options":[{"id":"a","texte":"Il conclut de ce doute que rien n’est vrai ni connaissable"},{"id":"b","texte":"Il l’abandonne dès qu’il rencontre la première objection sérieuse"},{"id":"c","texte":"Il s’en sert comme d’une méthode pour trouver un point fixe"},{"id":"d","texte":"Il l’applique seulement aux croyances des autres, jamais aux siennes"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m17","m18"]},"explication":"Ce sont **doute** et **pense** : douter, c’est penser, donc exister."},{"cle":{"type":"ordre","ids":["b","c","a","d"]},"explication":"Le raisonnement va **du doute à la certitude** : je doute, donc je pense, donc j’existe."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le doute est **méthodique** : il ne ruine pas le savoir, il cherche le point fixe à partir duquel le reconstruire."}]$ex$::jsonb),
  ('8df57df5-b863-5c0d-9e7c-13b2f0214ddc'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Trois manières d’être conscient","competence":"analyser-document","situation":"Quatre scènes de la vie d’un lycée montrent des degrés différents de conscience. Classe-les, repère celle qui juge ce qui vaut, puis complète la définition.","documents":[{"id":"scenes","type":"fiche","modele":"affiche","entete":"Quatre scènes","sousTitre":"Scènes écrites pour l’exercice","emoji":"🧠","teinte":"violet","lignes":[{"texte":"Hugo sent le soleil chauffer son visage.","id":"z1"},{"texte":"Léa claque la porte, puis se demande pourquoi elle a crié.","id":"z2"},{"texte":"Nour rend un sac trouvé dans la cour, alors que personne ne l’a vue : « C’est ce qu’il faut faire. »","id":"z3"},{"texte":"Sacha se dit : « Je me vois hésiter devant ce sujet. »","id":"z4"}],"pied":"Les trois degrés du cours"}],"questions":[{"enonce":"Range chaque scène selon le degré de conscience qu’elle illustre.","aide":"Sentir, se regarder sentir, juger ce qui vaut.","type":"categories","categories":[{"id":"c0","texte":"Immédiate"},{"id":"c1","texte":"Réfléchie"},{"id":"c2","texte":"Morale"}],"items":[{"id":"i0","texte":"Nour rend le sac : c’est ce qu’il faut faire"},{"id":"i1","texte":"Léa se demande pourquoi elle a crié"},{"id":"i2","texte":"Hugo sent le soleil sur son visage"},{"id":"i3","texte":"Sacha se voit hésiter"}]},{"enonce":"Touche la scène où la conscience juge ce qui vaut, et non ce qui est.","aide":"Cherche celle où l’on parle de ce qu’« il faut » faire.","type":"zone","document":"scenes","multiple":false},{"enonce":"Complète : être conscient, ce n’est pas seulement percevoir, c’est ___ que l’on perçoit.","aide":"Pense à *cum scientia* : accompagné de…","type":"trous","segments":["Être conscient, ce n’est pas seulement percevoir, c’est ",0," que l’on perçoit."],"banque":["espérer","nier","oublier","savoir"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c2","i1":"c1","i2":"c0","i3":"c1"}},"explication":"L’**immédiate** est le rapport spontané au monde ; la **réfléchie** est le retour sur soi ; la **morale** juge non ce qui est, mais ce qui vaut."},{"cle":{"type":"zone","ids":["z3"]},"explication":"C’est la scène de **Nour** : elle ne constate rien, elle juge une action bonne."},{"cle":{"type":"trous","trous":[["savoir"]]},"affichage":"savoir","explication":"C’est **savoir** que l’on perçoit : la conscience est un savoir qui accompagne la perception."}]$ex$::jsonb),
  ('8df57df5-b863-5c0d-9e7c-13b2f0214ddc'::uuid, 3, 3, 15, 50, 3,
   $ex${"titre":"Trois soupçons sur le « je pense »","competence":"argumenter","situation":"Sur un forum de révision, trois élèves résument chacun un soupçon porté contre la transparence de la conscience. À toi de retrouver les penseurs et de poser la bonne question de dissertation.","documents":[{"id":"forum","type":"texte","genre":"source","titre":"Le forum de philo","blocs":["**Anaïs** : « Je ne me connais jamais tel que je suis en moi-même, seulement tel que je m’apparais. »","**Malik** : « Ce que je décide n’est qu’une petite partie de ce qui se joue en moi, et pas la plus décisive. »","**Zoé** : « Ma conscience n’est pas une chose logée en moi : c’est un mouvement vers le monde, sans contenu propre. »"],"source":"Phrases écrites pour l’exercice, dans l’esprit de chaque auteur"},{"id":"sujet","type":"tableau","titre":"Un sujet de dissertation","colonnes":["Sujet","Enjeu"],"lignes":[["La conscience de soi est-elle une connaissance de soi ?","Se voir penser suffit-il à se connaître ?"]],"enteteLignes":false}],"questions":[{"enonce":"Associe chaque élève au penseur dont il reprend l’idée.","aide":"Phénomène, petite partie du psychisme, conscience vide.","type":"association","gauche":[{"id":"g0","texte":"Anaïs"},{"id":"g1","texte":"Malik"},{"id":"g2","texte":"Zoé"}],"droite":[{"id":"d0","texte":"Sartre"},{"id":"d1","texte":"Freud"},{"id":"d2","texte":"Kant"}]},{"enonce":"Touche le mot qui dit, chez Zoé, ce qu’est la conscience à la place d’une chose.","aide":"Une chose reste en place ; la conscience, elle, se dirige vers…","type":"zone","document":"forum","multiple":false},{"enonce":"Sujet du tableau : quelle est la bonne problématique ?","aide":"Une problématique transforme le sujet en une question qui fait débat.","type":"choix","options":[{"id":"a","texte":"Quels sont les trois degrés de la conscience et comment les distinguer les uns des autres ?"},{"id":"b","texte":"Puisque je me vois penser, ce retour sur moi me donne-t-il accès à ce que je suis vraiment ?"},{"id":"c","texte":"Qui a inventé le mot « conscience » et à quelle époque de l’histoire de la philosophie ?"},{"id":"d","texte":"Faut-il toujours dire ce que l’on pense, même quand cela peut blesser quelqu’un d’autre ?"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"**Anaïs** suit Kant (je ne me connais que comme phénomène), **Malik** Freud (la conscience n’est qu’une petite partie du psychisme), **Zoé** Sartre (la conscience n’est pas une chose)."},{"cle":{"type":"zone","ids":["m55"]},"explication":"C’est **mouvement** : pour Sartre, la conscience n’est pas un contenu, c’est un élan vers le monde."},{"cle":{"type":"choix","ids":["b"]},"explication":"La bonne problématique part de l’évidence (je me vois penser) et la met en tension : **ce retour sur moi est-il une connaissance ?**"}]$ex$::jsonb),
  ('f712a205-ddcf-50d4-bebf-a32c2e2aa4e2'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Ce qui n’est pas l’inconscient","competence":"analyser-document","situation":"Quatre faits de la vie courante sont présentés sur une affiche de révision. Tous ne relèvent pas de l’inconscient freudien : à toi de faire le tri.","documents":[{"id":"faits","type":"fiche","modele":"affiche","entete":"Quatre faits","sousTitre":"Exemples écrits pour l’exercice","emoji":"🌀","teinte":"violet","lignes":[{"texte":"Ma digestion se fait pendant que je dors.","id":"z1"},{"texte":"Je cherche mes lunettes partout : elles sont sur mon nez, je n’y prêtais pas attention.","id":"z2"},{"texte":"En voulant dire « ma sœur », Clara dit « ma mère » au moment où elles se disputent.","id":"z3"},{"texte":"Un rêve dont le sens est déguisé revient chaque nuit à Rayan.","id":"z4"}],"pied":"Non-conscient, inattention ou inconscient psychique ?"}],"questions":[{"enonce":"Touche le fait qui n’a pas de sens : ce n’est pas une pensée.","aide":"Quel fait n’est pas une pensée, mais une fonction du corps ?","type":"zone","document":"faits","multiple":false},{"enonce":"Range chaque fait dans la bonne catégorie.","aide":"Seul l’inconscient psychique a un sens et agit.","type":"categories","categories":[{"id":"c0","texte":"Non-conscient biologique"},{"id":"c1","texte":"Inattention"},{"id":"c2","texte":"Inconscient psychique"}],"items":[{"id":"i0","texte":"Les lunettes sur le nez, qu’on ne voyait pas"},{"id":"i1","texte":"Le lapsus « ma mère » pour « ma sœur »"},{"id":"i2","texte":"Le rêve au sens déguisé"},{"id":"i3","texte":"La digestion pendant le sommeil"}]},{"enonce":"Pourquoi les lunettes oubliées ne relèvent-elles pas de l’inconscient freudien ?","aide":"Que se passe-t-il dès que j’y prête attention ?","type":"choix","options":[{"id":"a","texte":"Parce que Clara les a cachées volontairement et en avait parfaitement conscience"},{"id":"b","texte":"Parce qu’on les retrouve toujours au bout de quelques minutes de recherche"},{"id":"c","texte":"L’inattention est réversible : il suffit d’y prêter attention"},{"id":"d","texte":"Parce qu’elles sont un simple objet matériel, qui ne peut rien signifier"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"C’est **la digestion** : un processus biologique, sans sens ni représentation."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c2","i2":"c2","i3":"c0"}},"explication":"Seuls le **lapsus** et le **rêve** ont un sens et agissent : c’est l’inconscient psychique. La digestion est biologique ; les lunettes relèvent de l’inattention."},{"cle":{"type":"choix","ids":["c"]},"explication":"L’inattention est **réversible** : en y faisant attention, je retrouve l’objet. Ce qui est refoulé, lui, ne revient pas par un simple effort."}]$ex$::jsonb),
  ('f712a205-ddcf-50d4-bebf-a32c2e2aa4e2'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Quatre retours du refoulé","competence":"analyser-texte","situation":"Un psychologue imaginaire raconte quatre scènes à son carnet. Chacune illustre une voie par laquelle le désir refoulé revient déguisé.","documents":[{"id":"carnet","type":"texte","genre":"recit","titre":"Le carnet du docteur","blocs":["Paul, qui redoute la réunion de lundi, oublie d’y aller alors qu’il l’avait notée trois fois.","Éva veut dire « Je suis contente de te voir » et déclare : « Je suis contente de te fuir. »","Amel rêve qu’elle s’enfuit d’une salle d’examen qu’elle a pourtant préparée avec enthousiasme.","Un pianiste sent sa main se paralyser, sans cause organique, juste avant un concert qu’il n’a jamais vraiment voulu donner."],"source":"Scènes écrites pour l’exercice"}],"questions":[{"enonce":"Associe chaque scène à la voie de retour qu’elle illustre.","aide":"Un acte, un mot, une nuit, un corps.","type":"association","gauche":[{"id":"g0","texte":"Paul oublie la réunion"},{"id":"g1","texte":"Éva dit « te fuir » pour « te voir »"},{"id":"g2","texte":"Amel s’enfuit dans son sommeil"},{"id":"g3","texte":"La main du pianiste se paralyse"}],"droite":[{"id":"d0","texte":"Le lapsus"},{"id":"d1","texte":"Le symptôme"},{"id":"d2","texte":"Le rêve"},{"id":"d3","texte":"L’acte manqué"}]},{"enonce":"Touche le verbe qui fait de la scène de Paul un acte manqué.","aide":"Il n’a pas fait ce qu’il avait pourtant noté trois fois.","type":"zone","document":"carnet","multiple":false},{"enonce":"Complète : le lapsus est un mot pour un autre qui dit ce qu’on ___.","aide":"Ce qu’on garde pour soi.","type":"trous","segments":["Le lapsus est un mot pour un autre qui dit ce qu’on ",0,"."],"banque":["oublie","prouve","ignore","tait"]},{"enonce":"Quelle idée de Freud rend ces quatre scènes interprétables au lieu d’absurdes ?","aide":"Si rien n’est dû au hasard, tout a un sens.","type":"choix","options":[{"id":"a","texte":"Le hasard pur gouverne nos actes, y compris les oublis et les lapsus"},{"id":"b","texte":"La conscience contrôle et connaît tout ce que nous faisons et disons"},{"id":"c","texte":"Le corps seul explique tout ce qui se passe dans la vie psychique"},{"id":"d","texte":"Le déterminisme psychique : rien n’est fortuit dans la vie psychique"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g2":"d2","g0":"d3"}},"explication":"L’**acte manqué** est un acte réussi d’une autre intention ; le **lapsus** dit ce qu’on tait ; le **rêve** est la voie royale ; le **symptôme** est un compromis entre le désir et l’interdit."},{"cle":{"type":"zone","ids":["m7"]},"explication":"C’est **oublie** : cet oubli n’est pas banal, il réalise le désir d’éviter la réunion."},{"cle":{"type":"trous","trous":[["tait","cache","refoule"]]},"affichage":"tait","explication":"Le lapsus dit **ce qu’on tait** : le refoulé trouve un chemin détourné vers la parole."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le **déterminisme psychique** dit que rien n’est fortuit : ces actes ont un sens qu’on peut chercher."}]$ex$::jsonb),
  ('f712a205-ddcf-50d4-bebf-a32c2e2aa4e2'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"La censure peut-elle ignorer ce qu’elle censure ?","competence":"argumenter","situation":"Un court texte adapté de Sartre attaque l’idée même de refoulement. Confronte-le aux deux topiques de Freud, puis pose la bonne question de dissertation.","documents":[{"id":"sartre","type":"texte","genre":"source","titre":"L’objection de la censure","blocs":["Si la censure refoule un désir, elle doit savoir ce qu’elle refoule ; or savoir, c’est être conscient. La censure est donc consciente. Il n’y a pas d’inconscient : il y a une conscience de mauvaise foi, qui se dérobe à sa propre liberté."],"source":"D’après Sartre, *L’Être et le Néant* (1943) — texte adapté"},{"id":"topiques","type":"tableau","titre":"Les deux topiques de Freud","colonnes":["Topique","Instances","Ce qu’elle décrit"],"lignes":[["Première","Inconscient, préconscient, conscient","Des lieux et un accès"],["Seconde","Ça, Moi, Surmoi","Des forces en conflit"]],"enteteLignes":true}],"questions":[{"enonce":"Quelle est l’objection de Sartre en une phrase ?","aide":"Relis la première phrase du texte.","type":"choix","options":[{"id":"a","texte":"Le Moi n’est qu’un organe du cerveau, sans aucun rôle dans la censure"},{"id":"b","texte":"Pour censurer un désir, la censure doit déjà le connaître, donc en être consciente"},{"id":"c","texte":"Les désirs refoulés n’existent pas, puisque personne ne peut jamais les observer"},{"id":"d","texte":"Les rêves n’ont aucun sens, puisqu’aucun souvenir ne permet de les interpréter"}],"multiple":false},{"enonce":"Touche les deux mots par lesquels Sartre remplace le mot « refoulement ».","aide":"Il parle d’une conscience qui se ment à elle-même.","type":"zone","document":"sartre","multiple":true},{"enonce":"Associe chaque instance de la seconde topique à son rôle.","aide":"Le tableau donne les noms ; le cours dit ce que chaque instance porte.","type":"association","gauche":[{"id":"g0","texte":"Le Ça"},{"id":"g1","texte":"Le Moi"},{"id":"g2","texte":"Le Surmoi"}],"droite":[{"id":"d0","texte":"Les interdits intériorisés"},{"id":"d1","texte":"Le siège des pulsions"},{"id":"d2","texte":"L’instance qui compose avec le réel"}]},{"enonce":"« L’inconscient excuse-t-il nos actes ? » Quelle est la bonne problématique ?","aide":"La problématique oppose explication et responsabilité.","type":"choix","options":[{"id":"a","texte":"Freud était-il médecin avant de devenir le fondateur de la psychanalyse moderne ?"},{"id":"b","texte":"Si une part de moi m’échappe, en quel sens suis-je encore responsable de mes actes ?"},{"id":"c","texte":"Quels sont les trois noms donnés par Freud aux instances de l’appareil psychique ?"},{"id":"d","texte":"Le rêve a-t-il le même sens pour tout le monde, ou seulement pour celui qui le fait ?"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["b"]},"explication":"La censure devrait **connaître ce qu’elle refoule** ; elle serait donc consciente, et l’inconscient perdrait son sens."},{"cle":{"type":"zone","ids":["m37","m38"]},"explication":"Sartre parle de **mauvaise foi** : une fuite de la conscience devant sa liberté, dont on reste responsable."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"Le **Ça** porte les pulsions, le **Moi** le réel, le **Surmoi** les interdits : d’où les forces en conflit."},{"cle":{"type":"choix","ids":["b"]},"explication":"La question centrale du chapitre : l’inconscient **explique-t-il ou excuse-t-il** ? La bonne problématique met la responsabilité en tension avec ce qui m’échappe."}]$ex$::jsonb),
  ('555a9a35-e78f-5612-8d80-3c1a441becb1'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Deux sens du mot « nature »","competence":"analyser-document","situation":"Quatre phrases utilisent le mot « nature », mais pas toujours dans le même sens. Une dissertation commence par y mettre de l’ordre.","documents":[{"id":"phrases","type":"fiche","modele":"affiche","entete":"Quatre phrases","sousTitre":"Phrases écrites pour l’exercice","emoji":"🌿","teinte":"vert","lignes":[{"texte":"Elle cherche la nature de ce phénomène.","id":"z1"},{"texte":"Nous partons marcher dans la nature.","id":"z2"},{"texte":"La nature de l’argent, c’est d’être échangé.","id":"z3"},{"texte":"La nature est menacée par le réchauffement.","id":"z4"}],"pied":"Essence ou ensemble ?"}],"questions":[{"enonce":"Touche les deux phrases où « nature » veut dire : ce qu’une chose est.","aide":"Dans ces phrases, on cherche l’essence d’une chose.","type":"zone","document":"phrases","multiple":true},{"enonce":"Range chaque phrase selon le sens du mot « nature ».","aide":"Ce qu’une chose est, ou ce qui existe hors de l’homme ?","type":"categories","categories":[{"id":"c0","texte":"L’essence d’une chose"},{"id":"c1","texte":"L’ensemble de ce qui existe sans l’homme"}],"items":[{"id":"i0","texte":"Nous partons marcher dans la nature"},{"id":"i1","texte":"La nature est menacée par le réchauffement"},{"id":"i2","texte":"Elle cherche la nature de ce phénomène"},{"id":"i3","texte":"La nature de l’argent, c’est d’être échangé"}]},{"enonce":"Pour un sujet sur la nature, quelle première étape de la dissertation est la plus sûre ?","aide":"Le mot sert à tout.","type":"choix","options":[{"id":"a","texte":"Éviter de définir le mot"},{"id":"b","texte":"Raconter un paysage de montagne"},{"id":"c","texte":"Distinguer les sens du mot « nature »"},{"id":"d","texte":"Citer trois auteurs sans les relier"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z3"]},"explication":"Ce sont les phrases sur **la nature du phénomène** et **la nature de l’argent** : nature = essence."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"Quand on parle de « la nature de… », c’est l’**essence** ; quand on parle de « la nature » tout court, c’est l’**ensemble** de ce qui existe sans l’homme."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le mot « nature » sert à tout : on commence toujours par **distinguer ses sens** avant de discuter."}]$ex$::jsonb),
  ('555a9a35-e78f-5612-8d80-3c1a441becb1'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Trois hommes, trois natures humaines","competence":"analyser-texte","situation":"Trois lycéens imaginaires défendent chacun une vision de l’état de nature et de la nature humaine. Retrouve leurs maîtres, trie ce que la société apporte, puis corrige un contresens.","documents":[{"id":"lyceens","type":"texte","genre":"source","titre":"Le débat du lundi","blocs":["**Inès** : « Sans pouvoir commun, chacun craindrait chacun : la vie serait une guerre permanente. »","**Yanis** : « L’homme naturel est paisible et ignorant ; c’est la propriété qui a apporté l’inégalité. »","**Chloé** : « Il n’y a aucune nature humaine donnée d’avance : on se définit par ce qu’on fait. »"],"source":"Phrases écrites pour l’exercice, dans l’esprit de chaque auteur"}],"questions":[{"enonce":"Associe chaque lycéen au philosophe dont il reprend l’idée.","aide":"Guerre de tous contre tous, propriété et inégalité, pas de nature humaine.","type":"association","gauche":[{"id":"g0","texte":"Inès"},{"id":"g1","texte":"Yanis"},{"id":"g2","texte":"Chloé"}],"droite":[{"id":"d0","texte":"Rousseau"},{"id":"d1","texte":"Sartre"},{"id":"d2","texte":"Hobbes"}]},{"enonce":"Qui apporte quoi ? Range ce que la société ajoute à l’état de nature.","aide":"Hobbes y gagne, Rousseau y perd.","type":"categories","categories":[{"id":"c0","texte":"Selon Hobbes"},{"id":"c1","texte":"Selon Rousseau"}],"items":[{"id":"i0","texte":"La sécurité garantie par un pouvoir commun"},{"id":"i1","texte":"La paix, par un souverain"},{"id":"i2","texte":"L’inégalité entre les hommes"},{"id":"i3","texte":"La propriété privée"}]},{"enonce":"Complète : l’état de nature est une fiction ___ : il sert à mesurer ce que la société nous a fait.","aide":"Ce n’est pas un fait mais un outil de pensée.","type":"trous","segments":["L’état de nature est une fiction ",0," : il sert à mesurer ce que la société nous a fait."],"banque":["vécue","méthodique","historique","archéologique"]},{"enonce":"Sartre compare l’homme à un coupe-papier. Que veut-il montrer ?","aide":"Un artisan a une idée en tête avant de fabriquer.","type":"choix","options":[{"id":"a","texte":"Tout objet fabriqué a une âme, comme l’homme, et c’est ce qui les rend comparables"},{"id":"b","texte":"L’homme est un outil fabriqué par la société, avec une fonction précise dès la naissance"},{"id":"c","texte":"L’homme naît bon par nature, puis la société le corrompt en lui imposant des rôles fixes"},{"id":"d","texte":"Le coupe-papier a une essence fixée avant d’exister ; l’homme existe d’abord, sans essence d’avance"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"**Inès** défend Hobbes, **Yanis** Rousseau, **Chloé** Sartre (« l’existence précède l’essence »)."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1"}},"explication":"Pour **Hobbes**, la société apporte la sécurité ; pour **Rousseau**, la propriété, l’inégalité et la corruption."},{"cle":{"type":"trous","trous":[["methodique"]]},"affichage":"méthodique","explication":"C’est une fiction **méthodique** : la traiter comme un fait historique est le contresens le plus fréquent."},{"cle":{"type":"choix","ids":["d"]},"explication":"Un coupe-papier est conçu avant d’exister ; pour l’homme, **l’existence précède l’essence** : rien n’est donné d’avance."}]$ex$::jsonb),
  ('555a9a35-e78f-5612-8d80-3c1a441becb1'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Maîtres et possesseurs, ou responsables ?","competence":"argumenter","situation":"Dans une commune imaginaire, un conseil municipal hésite sur l’avenir de sa forêt. Tu confrontes son débat à la formule célèbre de Descartes, puis tu en tires un sujet de dissertation.","documents":[{"id":"descartes","type":"texte","genre":"source","titre":"Une promesse de la science","blocs":["Les connaissances nouvelles permettent de fabriquer des outils qui nous font jouir sans peine des fruits de la terre. Nous pouvons ainsi nous rendre comme maîtres et possesseurs de la nature."],"source":"D’après Descartes, *Discours de la méthode* (1637) — texte adapté"},{"id":"conseil","type":"texte","genre":"source","titre":"Le conseil municipal d’Aubelle","blocs":["**Le maire** : « Notre forêt est une réserve de bois : nous la coupons au rythme de nos besoins. »","**Une élue** : « Nos coupes d’aujourd’hui retirent une forêt à nos petits-enfants. Nous avons une responsabilité envers eux. »"],"source":"Débat écrit pour l’exercice, commune imaginaire"}],"questions":[{"enonce":"Touche les deux mots qui résument le programme cartésien.","aide":"Descartes veut devenir comme les… de la nature.","type":"zone","document":"descartes","multiple":true},{"enonce":"Touche le mot par lequel le maire réduit la forêt à ce qu’elle nous sert.","aide":"Un stock qu’on garde en réserve.","type":"zone","document":"conseil","multiple":false},{"enonce":"Associe chaque personnage à la position qu’il incarne.","aide":"L’un exploite, l’autre pense aux générations futures.","type":"association","gauche":[{"id":"g0","texte":"Le maire"},{"id":"g1","texte":"L’élue"}],"droite":[{"id":"d0","texte":"Dans l’esprit de Hans Jonas"},{"id":"d1","texte":"Dans l’esprit de Descartes"}]},{"enonce":"« Faut-il maîtriser la nature ? » Quelle problématique convient le mieux ?","aide":"Il faut opposer l’usage à la responsabilité.","type":"choix","options":[{"id":"a","texte":"La nature est-elle belle, et la beauté d’un paysage est-elle la même pour tous ?"},{"id":"b","texte":"Peut-on vouloir user de la nature sans compromettre ce qui permet à l’humanité de durer ?"},{"id":"c","texte":"Y a-t-il encore des forêts en Europe, et quelle part du territoire occupent-elles ?"},{"id":"d","texte":"Qui a écrit le *Discours de la méthode* et dans quel contexte l’a-t-il publié en 1637 ?"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m25","m27"]},"explication":"Ce sont **maîtres** et **possesseurs** : connaître la nature pour l’utiliser."},{"cle":{"type":"zone","ids":["m6"]},"explication":"Le maire parle de **réserve** : la nature est un stock à exploiter, dans l’esprit cartésien."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1"}},"explication":"Le maire prolonge le programme cartésien ; l’élue pense comme **Jonas** : agir en restant compatible avec la permanence d’une vie authentiquement humaine sur terre."},{"cle":{"type":"choix","ids":["b"]},"explication":"La crise écologique **retourne le programme cartésien** : la nature devient une responsabilité. La bonne problématique met face à face usage et permanence."}]$ex$::jsonb),
  ('1af1e7a9-efc1-52b8-adaa-c01f4b863ba9'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Plaisir, joie ou bonheur ?","competence":"analyser-document","situation":"Quatre moments de vie sont affichés sur un tableau de classe. Tous ne sont pas du même ordre : plaisir fugitif, joie intense ou état durable ?","documents":[{"id":"moments","type":"fiche","modele":"affiche","entete":"Quatre moments","sousTitre":"Situations écrites pour l’exercice","emoji":"🙂","teinte":"ambre","lignes":[{"texte":"Ce matin, une part de tarte aux pommes.","id":"z1"},{"texte":"Le but marqué à la dernière seconde : cris, larmes, bras en l’air.","id":"z2"},{"texte":"Dix ans d’une vie qui te convient : un métier qui a du sens, des amis, du temps.","id":"z3"},{"texte":"Un bain chaud après une longue journée de marche.","id":"z4"}],"pied":"Plaisir, joie, bonheur"}],"questions":[{"enonce":"Range chaque moment dans la bonne catégorie.","aide":"Sensible et fugitif, intense et passager, durable et global.","type":"categories","categories":[{"id":"c0","texte":"Plaisir"},{"id":"c1","texte":"Joie"},{"id":"c2","texte":"Bonheur"}],"items":[{"id":"i0","texte":"Dix ans d’une vie qui convient"},{"id":"i1","texte":"Le but marqué à la dernière seconde"},{"id":"i2","texte":"Une part de tarte aux pommes"},{"id":"i3","texte":"Un bain chaud après la marche"}]},{"enonce":"Touche le moment qui relève du bonheur plutôt que du plaisir ou de la joie.","aide":"Cherche ce qui dure et concerne toute une vie.","type":"zone","document":"moments","multiple":false},{"enonce":"Complète : le bonheur est un état ___ et global, alors que le plaisir est ponctuel.","aide":"L’opposé de fugitif.","type":"trous","segments":["Le bonheur est un état ",0," et global, alors que le plaisir est ponctuel."],"banque":["fugitif","bruyant","sensible","durable"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c2","i1":"c1","i2":"c0","i3":"c0"}},"explication":"Le **plaisir** est sensible et fugitif ; la **joie** est une émotion intense et passagère ; le **bonheur** est un état durable et global."},{"cle":{"type":"zone","ids":["z3"]},"explication":"C’est **les dix ans d’une vie qui convient** : le bonheur est un état de satisfaction complète et durable."},{"cle":{"type":"trous","trous":[["durable"]]},"affichage":"durable","explication":"Le bonheur est **durable** : c’est ce qui le distingue du plaisir ou de la joie."}]$ex$::jsonb),
  ('1af1e7a9-efc1-52b8-adaa-c01f4b863ba9'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Trier ses désirs comme Épicure","competence":"raisonner","situation":"Une famille fictive prépare son menu de vœux pour l’année. Épicure aurait classé les désirs en trois familles. À toi de l’imiter, puis de distinguer trois recettes de la sagesse antique.","documents":[{"id":"voeux","type":"fiche","modele":"affiche","entete":"Vœux de l’année","sousTitre":"Liste écrite pour l’exercice","emoji":"📝","teinte":"vert","lignes":[{"texte":"Boire un verre d’eau quand on a soif.","id":"z1"},{"texte":"Organiser un festin aux truffes.","id":"z2"},{"texte":"Devenir célèbre.","id":"z3"},{"texte":"Manger un repas simple pour calmer la faim.","id":"z4"},{"texte":"Devenir milliardaire.","id":"z5"}],"pied":"Naturels et nécessaires ? Naturels seulement ? Ni l’un ni l’autre ?"}],"questions":[{"enonce":"Range chaque désir selon la classification d’Épicure.","aide":"Manger pour vivre, bien manger, la gloire et la richesse.","type":"categories","categories":[{"id":"c0","texte":"Naturel et nécessaire"},{"id":"c1","texte":"Naturel, non nécessaire"},{"id":"c2","texte":"Ni naturel ni nécessaire"}],"items":[{"id":"i0","texte":"Un verre d’eau quand on a soif"},{"id":"i1","texte":"Devenir célèbre"},{"id":"i2","texte":"Un repas simple contre la faim"},{"id":"i3","texte":"Un festin aux truffes"},{"id":"i4","texte":"Devenir milliardaire"}]},{"enonce":"Touche les deux désirs qu’Épicure conseille d’écarter d’abord.","aide":"Ce sont ceux qui sont vains : ni naturels ni nécessaires.","type":"zone","document":"voeux","multiple":true},{"enonce":"Associe chaque école à sa recette du bonheur.","aide":"Trier, distinguer, accomplir.","type":"association","gauche":[{"id":"g0","texte":"Épicure"},{"id":"g1","texte":"Les stoïciens"},{"id":"g2","texte":"Aristote"}],"droite":[{"id":"d0","texte":"Trier ses désirs pour atteindre l’ataraxie"},{"id":"d1","texte":"Vivre selon la vertu dans une vie accomplie"},{"id":"d2","texte":"Distinguer ce qui dépend de nous du reste"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c0","i1":"c2","i2":"c0","i3":"c1","i4":"c2"}},"explication":"Boire et manger simplement sont **naturels et nécessaires** ; le festin est **naturel mais non nécessaire** ; gloire et richesse sont **ni naturels ni nécessaires**."},{"cle":{"type":"zone","ids":["z3","z5"]},"explication":"Ce sont **la célébrité** et **la richesse** : des désirs vains qui troublent l’âme."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"**Épicure** trie les désirs, les **stoïciens** distinguent ce qui dépend de nous, **Aristote** cherche une activité conforme à la vertu."}]$ex$::jsonb),
  ('1af1e7a9-efc1-52b8-adaa-c01f4b863ba9'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Faut-il chercher le bonheur ?","competence":"argumenter","situation":"Tu prépares une dissertation sur le bonheur. Un texte adapté de Pascal et trois répliques d’élèves te donnent la matière : à toi de les attribuer, de juger l’objection la plus forte et d’organiser un plan.","documents":[{"id":"pascal","type":"texte","genre":"source","titre":"Fuir le repos","blocs":["Les hommes courent après le bruit et l’agitation pour ne pas avoir à demeurer seuls dans une chambre, face à ce qu’ils sont. Ils cherchent moins le bonheur que le divertissement qui fait oublier leur condition."],"source":"D’après Pascal, *Pensées* — texte adapté"},{"id":"repliques","type":"texte","genre":"source","titre":"Trois répliques","blocs":["**A** : « La vie oscille entre la souffrance du manque et l’ennui quand on est comblé. »","**B** : « La morale ne m’apprend pas à être heureux, mais à me rendre digne de l’être. »","**C** : « Nous ne cherchons pas le bonheur mais l’agitation qui nous fait oublier notre condition. »"],"source":"Répliques écrites pour l’exercice, dans l’esprit de chaque auteur"}],"questions":[{"enonce":"Touche les deux mots qui nomment ce que les hommes cherchent pour fuir le repos.","aide":"Ce qui emplit la chambre quand on ne veut pas être seul avec soi.","type":"zone","document":"pascal","multiple":true},{"enonce":"Associe chaque réplique à son auteur.","aide":"Manque et ennui, dignité, divertissement.","type":"association","gauche":[{"id":"g0","texte":"A"},{"id":"g1","texte":"B"},{"id":"g2","texte":"C"}],"droite":[{"id":"d0","texte":"Kant"},{"id":"d1","texte":"Schopenhauer"},{"id":"d2","texte":"Pascal"}]},{"enonce":"Pourquoi l’objection kantienne est-elle la plus redoutable en dissertation ?","aide":"Elle ne dit pas que le bonheur est impossible.","type":"choix","options":[{"id":"a","texte":"Elle défend le divertissement, car Kant y voit la meilleure voie vers le bonheur durable"},{"id":"b","texte":"Elle interdit d’être heureux, car Kant juge que le bonheur est toujours une faute morale"},{"id":"c","texte":"Elle prouve que le bonheur est impossible à atteindre, puisque tout désir en appelle un autre"},{"id":"d","texte":"Elle dit que le bonheur n’est pas le critère du bien : un homme heureux peut être injuste"}],"multiple":false},{"enonce":"Organise un plan pour « Le bonheur est-il l’affaire de la morale ? ».","aide":"Thèse, objection, dépassement.","type":"ordre","items":[{"id":"a","texte":"Tout homme veut être heureux : le bonheur est la fin de la vie"},{"id":"b","texte":"Dépassement : la morale apprend à se rendre digne d’être heureux"},{"id":"c","texte":"Mais le bonheur n’est pas le critère du bien"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5","m8"]},"explication":"Ce sont **bruit** et **agitation** : le divertissement."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"**A** est Schopenhauer (manque et ennui), **B** Kant (digne d’être heureux), **C** Pascal (le divertissement)."},{"cle":{"type":"choix","ids":["d"]},"explication":"Elle déplace la question : **le bonheur n’est pas le critère du bien**. Un homme heureux peut être injuste."},{"cle":{"type":"ordre","ids":["a","c","b"]},"explication":"Le plan va de la **thèse** (le bonheur comme fin) à l’**objection** (il n’est pas le critère du bien), puis au **dépassement** (se rendre digne de l’être)."}]$ex$::jsonb),
  ('15c7919c-6b47-5ac7-b80f-aae35ae12c84'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le maître et l’esclave","competence":"analyser-texte","situation":"Hegel imagine une relation de maître à esclave pour montrer ce que le travail fait à celui qui travaille. Lis, classe, conclus.","documents":[{"id":"hegel","type":"texte","genre":"source","titre":"Jouir ou travailler","blocs":["Le maître fait travailler l’esclave à sa place : il jouit de la chose sans l’avoir travaillée. L’esclave, lui, transforme la chose ; en la transformant, il forme le monde et se forme lui-même, et il y reconnaît son œuvre."],"source":"D’après Hegel, *Phénoménologie de l’esprit* (1807) — texte adapté"}],"questions":[{"enonce":"Touche le verbe qui dit ce que fait l’esclave de la chose.","aide":"Le maître consomme ; lui, il fait autre chose.","type":"zone","document":"hegel","multiple":false},{"enonce":"Range chaque trait du côté du maître ou de l’esclave.","aide":"Qui produit, qui consomme ?","type":"categories","categories":[{"id":"c0","texte":"Le maître"},{"id":"c1","texte":"L’esclave"}],"items":[{"id":"i0","texte":"Travaille la chose"},{"id":"i1","texte":"Se reconnaît dans son ouvrage"},{"id":"i2","texte":"Consomme sans rien produire"},{"id":"i3","texte":"Ne se reconnaît dans rien"}]},{"enonce":"Quel est le paradoxe de Hegel ?","aide":"Regarde qui se transforme.","type":"choix","options":[{"id":"a","texte":"Le travail est toujours une punition, et il ne transforme jamais celui qui l’accomplit"},{"id":"b","texte":"Celui qui obéit et travaille se forme, celui qui commande et jouit ne produit rien"},{"id":"c","texte":"L’esclave n’a aucune conscience de soi, puisqu’il ne fait qu’obéir aux ordres"},{"id":"d","texte":"Le maître travaille beaucoup plus que l’esclave, qui se contente de jouir de ses loisirs"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m21"]},"explication":"C’est **transforme** : en transformant la chose, l’esclave se transforme."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"Le **maître** consomme et ne se reconnaît dans rien ; l’**esclave** travaille et se reconnaît dans son œuvre."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le **travail forme** celui qui travaille : l’esclave se forme en formant le monde, alors que le maître stagne dans la jouissance."}]$ex$::jsonb),
  ('15c7919c-6b47-5ac7-b80f-aae35ae12c84'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Quand le travail nous échappe","competence":"argumenter","situation":"Marx oppose l’architecte et l’abeille, puis décrit comment le travail peut dépouiller l’ouvrier. Trois récits d’atelier illustrent trois formes d’aliénation.","documents":[{"id":"marx","type":"texte","genre":"source","titre":"L’architecte et l’abeille","blocs":["Une abeille construit des cellules qui feraient rougir plus d’un architecte. Mais ce qui distingue le pire architecte de l’abeille la plus habile, c’est qu’il a d’abord imaginé sa construction avant de la réaliser."],"source":"D’après Marx, *Le Capital* (1867) — texte adapté"},{"id":"recits","type":"fiche","modele":"affiche","entete":"Trois récits d’atelier","sousTitre":"Récits écrits pour l’exercice","emoji":"🏭","teinte":"brun","lignes":[{"texte":"Léo visse la même vis toute la journée, sans jamais voir le meuble fini.","id":"z1"},{"texte":"Samia fabrique des montres qui ne lui appartiendront jamais.","id":"z2"},{"texte":"Kévin échange huit heures de sa vie chaque jour contre un salaire.","id":"z3"}],"pied":"Trois formes d’aliénation"}],"questions":[{"enonce":"Touche le mot qui dit ce que l’architecte fait avant de construire.","aide":"Il le fait dans sa tête.","type":"zone","document":"marx","multiple":false},{"enonce":"Associe chaque récit à la forme d’aliénation qu’il illustre.","aide":"Parcelle, objet, temps de vie.","type":"association","gauche":[{"id":"g0","texte":"Léo visse la même vis"},{"id":"g1","texte":"Samia fabrique des montres"},{"id":"g2","texte":"Kévin vend ses journées"}],"droite":[{"id":"d0","texte":"Il vend sa force de travail"},{"id":"d1","texte":"La tâche est parcellisée"},{"id":"d2","texte":"L’objet lui échappe"}]},{"enonce":"Complète : Marx nomme ___ la situation où le travailleur ne se reconnaît plus dans son produit.","aide":"Le mot commence par un a.","type":"trous","segments":["Marx nomme ",0," la situation où le travailleur ne se reconnaît plus dans son produit."],"banque":["émancipation","vocation","jouissance","aliénation"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m32"]},"explication":"C’est **imaginé** : l’homme conçoit son ouvrage avant de le réaliser, ce que ne fait pas l’abeille."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"Léo ne voit plus le **tout** ; Samia ne possède pas ce qu’elle **produit** ; Kévin fait du **temps de sa vie** une marchandise."},{"cle":{"type":"trous","trous":[["alienation"]]},"affichage":"aliénation","explication":"Cette situation s’appelle l’**aliénation** : le travail défait celui qui travaille."}]$ex$::jsonb),
  ('15c7919c-6b47-5ac7-b80f-aae35ae12c84'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Travail, œuvre, action","competence":"analyser-document","situation":"Hannah Arendt distingue trois activités que la langue courante confond. Complète son tableau, classe des activités de la vie quotidienne, puis interroge notre société.","documents":[{"id":"arendt","type":"tableau","titre":"Trois activités","colonnes":["Activité","Ce qu’elle produit","Sa temporalité"],"lignes":[["?","Du consommable","Elle recommence sans fin"],["?","Un monde durable","Elle laisse une trace"],["?","Parole et initiative politiques","Elle ouvre du nouveau"]],"enteteLignes":true},{"id":"activites","type":"fiche","modele":"affiche","entete":"Quatre activités","sousTitre":"Exemples écrits pour l’exercice","emoji":"🧰","teinte":"bleu","lignes":[{"texte":"Préparer le repas de chaque soir.","id":"z1"},{"texte":"Sculpter une statue qui restera sur la place.","id":"z2"},{"texte":"Proposer un projet nouveau à l’assemblée du quartier.","id":"z3"},{"texte":"Faire la vaisselle après le repas.","id":"z4"}],"pied":"Travail, œuvre ou action ?"}],"questions":[{"enonce":"Complète les lignes du tableau : la première est le ___, la deuxième l’___ et la troisième l’___.","aide":"Consommable, durable, politique.","type":"trous","segments":["La première ligne est le ",0,", la deuxième l’",1," et la troisième l’",2,"."],"banque":["loisir","travail","action","œuvre"]},{"enonce":"Range chaque activité dans la bonne catégorie.","aide":"Ce qui recommence, ce qui dure, ce qui ouvre du nouveau.","type":"categories","categories":[{"id":"c0","texte":"Travail"},{"id":"c1","texte":"Œuvre"},{"id":"c2","texte":"Action"}],"items":[{"id":"i0","texte":"Proposer un projet à l’assemblée du quartier"},{"id":"i1","texte":"Faire la vaisselle"},{"id":"i2","texte":"Préparer le repas de chaque soir"},{"id":"i3","texte":"Sculpter une statue durable"}]},{"enonce":"Touche l’activité qui laisse une trace dans un monde durable.","aide":"Elle reste quand son auteur est parti.","type":"zone","document":"activites","multiple":false},{"enonce":"Que risque une société qui ne valorise plus que le travail ?","aide":"C’est la question ouverte d’Arendt.","type":"choix","options":[{"id":"a","texte":"De ne produire que des œuvres durables, sans jamais rien consommer"},{"id":"b","texte":"De ne plus savoir ce qu’elle fait de l’œuvre et de l’action humaines"},{"id":"c","texte":"De n’avoir plus besoin de personne, puisque tout s’y fait par le travail"},{"id":"d","texte":"De supprimer toute activité humaine, y compris le travail lui-même"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"trous","trous":[["travail"],["oeuvre"],["action"]]},"affichage":"travail · œuvre · action","explication":"Consommable qui recommence : le **travail** ; monde durable : l’**œuvre** ; parole et initiative : l’**action**."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c0","i2":"c0","i3":"c1"}},"explication":"Repas et vaisselle sont du **travail** ; la statue est une **œuvre** ; le projet proposé à l’assemblée est une **action**."},{"cle":{"type":"zone","ids":["z2"]},"explication":"C’est **la statue** : l’œuvre produit un monde durable."},{"cle":{"type":"choix","ids":["b"]},"explication":"Arendt laisse la question ouverte : une société qui ne valorise que le travail oublie ce qu’elle fait des **deux autres activités**, l’œuvre et l’action."}]$ex$::jsonb),
  ('a9c5fb62-742f-5f14-8097-2203333654b9'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"L’État ou la société ?","competence":"analyser-document","situation":"Sur une affiche de révision figurent six institutions ou groupes. L’État n’est pas la société : à toi de trier, puis de repérer le monopole décrit par Max Weber.","documents":[{"id":"liste","type":"fiche","modele":"affiche","entete":"Six acteurs","sousTitre":"Liste écrite pour l’exercice","emoji":"🏛️","teinte":"violet","lignes":[{"texte":"L’administration fiscale","id":"z1"},{"texte":"Une association de quartier","id":"z2"},{"texte":"La police nationale","id":"z3"},{"texte":"Une famille","id":"z4"},{"texte":"Un tribunal","id":"z5"},{"texte":"Un club de foot","id":"z6"}],"pied":"État ou société ?"}],"questions":[{"enonce":"Range chaque acteur : institution de l’État, ou élément de la société ?","aide":"L’État est l’institution qui détient le pouvoir politique.","type":"categories","categories":[{"id":"c0","texte":"État"},{"id":"c1","texte":"Société"}],"items":[{"id":"i0","texte":"Une famille"},{"id":"i1","texte":"L’administration fiscale"},{"id":"i2","texte":"Une association de quartier"},{"id":"i3","texte":"Un tribunal"},{"id":"i4","texte":"Un club de foot"},{"id":"i5","texte":"La police nationale"}]},{"enonce":"Touche l’acteur qui incarne le mieux le monopole de la violence physique légitime.","aide":"Qui peut contraindre physiquement dans le cadre de la loi ?","type":"zone","document":"liste","multiple":false},{"enonce":"Un policier peut arrêter un automobiliste, pas un simple passant. Pourquoi ?","aide":"Pense à la définition de Max Weber.","type":"choix","options":[{"id":"a","texte":"Parce que le simple passant n’a pas le permis de conduire"},{"id":"b","texte":"Seul l’État dispose d’une contrainte reconnue comme fondée en droit"},{"id":"c","texte":"Parce que le policier est physiquement plus fort que l’automobiliste"},{"id":"d","texte":"Parce que c’est une coutume ancienne, sans lien avec la loi"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0","i4":"c1","i5":"c0"}},"explication":"L’**État** regroupe l’administration, la police, les tribunaux ; la **société** inclut familles, associations, clubs."},{"cle":{"type":"zone","ids":["z3"]},"explication":"C’est **la police nationale** : elle exerce la contrainte reconnue comme légitime."},{"cle":{"type":"choix","ids":["b"]},"explication":"Seul l’État détient le **monopole de la violence légitime** : sa contrainte est reconnue comme fondée."}]$ex$::jsonb),
  ('a9c5fb62-742f-5f14-8097-2203333654b9'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Trois citoyens, trois contrats","competence":"analyser-texte","situation":"Trois citoyens imaginaires justifient à leur manière l’obéissance à l’État. Retrouve leurs maîtres, puis trie les notions clés.","documents":[{"id":"citoyens","type":"texte","genre":"source","titre":"Trois citoyens d’une cité imaginaire","blocs":["**Bastien** : « J’accepte d’obéir à un pouvoir fort, car sans lui chacun vivrait dans la peur de chacun. »","**Élise** : « Un gouvernement qui viole ma vie, ma liberté et mes biens n’a plus le droit de me commander. »","**Théo** : « Je n’obéis qu’à la loi que le peuple s’est donnée à lui-même. »"],"source":"Répliques écrites pour l’exercice, dans l’esprit de chaque auteur"}],"questions":[{"enonce":"Associe chaque citoyen au penseur dont il reprend l’idée.","aide":"Peur et sécurité, droits violés, loi que l’on se donne.","type":"association","gauche":[{"id":"g0","texte":"Bastien"},{"id":"g1","texte":"Élise"},{"id":"g2","texte":"Théo"}],"droite":[{"id":"d0","texte":"Locke"},{"id":"d1","texte":"Rousseau"},{"id":"d2","texte":"Hobbes"}]},{"enonce":"Range chaque notion du côté de son auteur.","aide":"Un monstre, des droits, un peuple souverain.","type":"categories","categories":[{"id":"c0","texte":"Hobbes"},{"id":"c1","texte":"Locke"},{"id":"c2","texte":"Rousseau"}],"items":[{"id":"i0","texte":"La volonté générale"},{"id":"i1","texte":"La sécurité par un pouvoir sans limite"},{"id":"i2","texte":"La souveraineté du peuple"},{"id":"i3","texte":"Les droits naturels : vie, liberté, propriété"},{"id":"i4","texte":"Le Léviathan"},{"id":"i5","texte":"Un État qui perd sa légitimité s’il viole les droits"}]},{"enonce":"Lequel des trois citoyens justifie le mieux le droit de résister à un gouvernement qui viole les droits ?","aide":"Cherche la limite explicite du pouvoir.","type":"choix","options":[{"id":"a","texte":"Théo, parce que la loi est ancienne, donc elle ne peut pas être contestée"},{"id":"b","texte":"Aucun des trois, car aucun citoyen n’a jamais le droit de résister au pouvoir"},{"id":"c","texte":"Bastien, parce que le pouvoir de l’État est sans limite, donc toujours obéi"},{"id":"d","texte":"Élise, parce que l’État qui viole les droits perd sa légitimité"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"**Bastien** suit Hobbes (la sécurité), **Élise** Locke (les droits naturels), **Théo** Rousseau (la volonté générale)."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c0","i2":"c2","i3":"c1","i4":"c0","i5":"c1"}},"explication":"**Hobbes** : Léviathan, sécurité ; **Locke** : droits naturels, légitimité perdue ; **Rousseau** : volonté générale, souveraineté du peuple."},{"cle":{"type":"choix","ids":["d"]},"explication":"Chez **Locke**, l’État a pour fin de garantir les droits naturels : s’il les viole, il perd sa légitimité."}]$ex$::jsonb),
  ('a9c5fb62-742f-5f14-8097-2203333654b9'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Pourquoi obéit-on sans contrainte ?","competence":"argumenter","situation":"La Boétie pose une question dérangeante que les théories du contrat n’éclairent pas. Tu confrontes son texte adapté aux réponses classiques, puis tu ordonnes un plan.","documents":[{"id":"boetie","type":"texte","genre":"source","titre":"Le tyran n’a que les yeux et les mains qu’on lui prête","blocs":["Ce tyran n’a de pouvoir que celui que vous lui donnez. Comment pourrait-il vous surveiller, s’il n’avait pas d’yeux que les vôtres ? Comment aurait-il des mains pour vous frapper, s’il ne les empruntait à vous-mêmes ? Soyez résolus à ne plus servir, et vous voilà libres."],"source":"D’après La Boétie, *Discours de la servitude volontaire* (vers 1549) — texte adapté"},{"id":"positions","type":"fiche","modele":"affiche","entete":"Quatre positions","sousTitre":"Synthèse écrite pour l’exercice","emoji":"⚖️","teinte":"bleu","lignes":[{"texte":"Marx : l’État est l’instrument de domination d’une classe.","id":"z1"},{"texte":"La Boétie : des millions d’hommes obéissent à un seul sans y être forcés.","id":"z2"},{"texte":"Réponse libérale : limiter l’État à la protection des droits.","id":"z3"},{"texte":"Réponse sociale : confier à l’État la réduction des inégalités.","id":"z4"}],"pied":"Critiques et réponses"}],"questions":[{"enonce":"Touche les deux parties du corps que, selon le texte, le tyran emprunte à ses sujets.","aide":"Pour surveiller et pour frapper.","type":"zone","document":"boetie","multiple":true},{"enonce":"Quelle question La Boétie pose-t-il, à la différence des théories du contrat ?","aide":"Ce n’est pas la contrainte qui l’étonne.","type":"choix","options":[{"id":"a","texte":"Pourquoi les lois changent-elles ?"},{"id":"b","texte":"Pourquoi le pouvoir contraint-il ?"},{"id":"c","texte":"Pourquoi obéit-on sans y être contraint ?"},{"id":"d","texte":"Pourquoi l’État est-il né ?"}],"multiple":false},{"enonce":"Touche la position qui correspond à la « servitude volontaire ».","aide":"Des millions d’hommes, un seul maître, aucune force.","type":"zone","document":"positions","multiple":false},{"enonce":"Organise un plan pour « Jusqu’où l’État doit-il aller ? ».","aide":"Deux réponses, puis la limite commune.","type":"ordre","items":[{"id":"a","texte":"L’État doit aussi réduire les inégalités : c’est la réponse sociale"},{"id":"b","texte":"La vraie limite : l’État doit rester contrôlable, car la tyrannie commence quand il ne l’est plus"},{"id":"c","texte":"L’État protège les droits : c’est la réponse libérale"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m22","m29"]},"explication":"Ce sont **yeux** et **mains** : sans ses sujets, le tyran n’a ni regard ni bras."},{"cle":{"type":"choix","ids":["c"]},"explication":"La Boétie ne demande pas pourquoi le pouvoir contraint, mais **pourquoi on lui obéit sans contrainte**."},{"cle":{"type":"zone","ids":["z2"]},"explication":"C’est la position de **La Boétie** : la servitude volontaire."},{"cle":{"type":"ordre","ids":["c","a","b"]},"explication":"Le plan expose la réponse **libérale**, la réponse **sociale**, puis la limite commune : **la tyrannie commence là où l’État n’est plus contrôlable**."}]$ex$::jsonb),
  ('2e894746-3958-5712-b2d1-3dc26f59c121'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Antigone contre Créon","competence":"analyser-texte","situation":"Dans la tragédie de Sophocle, Antigone défie un édit royal au nom d’autre chose que la loi de la cité. Une adaptation te permet de repérer le conflit.","documents":[{"id":"antigone","type":"texte","genre":"theatre","titre":"Acte 1, scène de l’édit","blocs":[{"personnage":"Créon","replique":"J’ai interdit d’enterrer Polynice. Quiconque le fera sera puni de mort."},{"personnage":"Antigone","replique":"Ton édit n’est pas plus fort que les lois non écrites des dieux, qui ne datent ni d’hier ni d’aujourd’hui."}],"source":"D’après Sophocle, *Antigone* — texte adapté"}],"questions":[{"enonce":"Touche les deux mots qui qualifient les lois au nom desquelles Antigone désobéit.","aide":"Elles ne figurent dans aucun code.","type":"zone","document":"antigone","multiple":true},{"enonce":"Range chaque élément : droit positif ou droit naturel ?","aide":"Ce qui est en vigueur ou ce qui permet de juger.","type":"categories","categories":[{"id":"c0","texte":"Droit positif"},{"id":"c1","texte":"Droit naturel"}],"items":[{"id":"i0","texte":"Un article du code pénal"},{"id":"i1","texte":"L’édit de Créon"},{"id":"i2","texte":"Un principe que l’on pense sans le lire dans un code"},{"id":"i3","texte":"Les lois non écrites invoquées par Antigone"}]},{"enonce":"L’édit de Créon est légal. Que dit Antigone à son sujet ?","aide":"Légal ne veut pas dire légitime.","type":"choix","options":[{"id":"a","texte":"Qu’il n’est pas une loi"},{"id":"b","texte":"Qu’il est sans importance"},{"id":"c","texte":"Qu’il est à la fois légal et juste"},{"id":"d","texte":"Qu’il est légal, mais illégitime"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m23","m24"]},"explication":"Ce sont **non** et **écrites** : les lois non écrites, en appui du droit naturel."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1"}},"explication":"Le **droit positif** est l’ensemble des règles en vigueur ; le **droit naturel** désigne des principes qui permettent de **juger** les lois."},{"cle":{"type":"choix","ids":["d"]},"explication":"Une loi peut être **légale sans être légitime** : Antigone en appelle à une justice au-dessus de l’édit."}]$ex$::jsonb),
  ('2e894746-3958-5712-b2d1-3dc26f59c121'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Distribuer ou corriger ?","competence":"analyser-document","situation":"Quatre situations sont affichées sur un panneau d’école de droit. Chacune relève d’une des deux justices d’Aristote.","documents":[{"id":"situations","type":"fiche","modele":"affiche","entete":"Quatre situations","sousTitre":"Situations écrites pour l’exercice","emoji":"⚖️","teinte":"ambre","lignes":[{"texte":"Un concours attribue ses bourses selon les résultats.","id":"z1"},{"texte":"Un tribunal condamne un voleur à rendre ce qu’il a pris, qu’il soit riche ou pauvre.","id":"z2"},{"texte":"Une prime est répartie selon les heures travaillées.","id":"z3"},{"texte":"Un dégât est réparé pour la même somme, quel que soit le statut de la victime.","id":"z4"}],"pied":"Distributive ou corrective ?"}],"questions":[{"enonce":"Range chaque situation selon la justice qu’elle illustre.","aide":"Mérite ou équilibre rompu ?","type":"categories","categories":[{"id":"c0","texte":"Distributive"},{"id":"c1","texte":"Corrective"}],"items":[{"id":"i0","texte":"Dégât réparé pour la même somme"},{"id":"i1","texte":"Le voleur rend ce qu’il a pris"},{"id":"i2","texte":"Prime selon les heures travaillées"},{"id":"i3","texte":"Bourses selon les résultats"}]},{"enonce":"Touche les deux situations où le statut des personnes ne doit pas compter.","aide":"Une égalité arithmétique, indépendante des personnes.","type":"zone","document":"situations","multiple":true},{"enonce":"Un tribunal jugerait selon le mérite social de l’accusé. Quelle erreur commet-il ?","aide":"Quelle justice devrait-il appliquer ?","type":"choix","options":[{"id":"a","texte":"Il fait de la distribution là où l’on attend de la correction"},{"id":"b","texte":"Il se montre trop sévère dans la peine qu’il inflige à l’accusé"},{"id":"c","texte":"Il confond le rôle du juge avec celui du législateur qui fait les lois"},{"id":"d","texte":"Il applique la justice divine au lieu de la justice des hommes"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"La justice **distributive** répartit selon le mérite ; la **corrective** rétablit l’équilibre rompu, sans regarder les personnes."},{"cle":{"type":"zone","ids":["z2","z4"]},"explication":"Ce sont le **voleur** et le **dégât** : la justice corrective rétablit l’équilibre, quel que soit le statut."},{"cle":{"type":"choix","ids":["a"]},"explication":"Confondre les deux justices, c’est **se tromper d’exigence** : le juge doit corriger un tort, pas distribuer des honneurs."}]$ex$::jsonb),
  ('2e894746-3958-5712-b2d1-3dc26f59c121'::uuid, 3, 3, 15, 50, 3,
   $ex${"titre":"Le voile d’ignorance du tournoi","competence":"raisonner","situation":"Quatre élèves imaginaires doivent fixer les règles d’un tournoi sans savoir dans quelle équipe ils seront, ni s’ils seront forts ou fragiles. Applique le raisonnement de Rawls.","documents":[{"id":"scene","type":"texte","genre":"source","titre":"Fixer les règles sans connaître sa place","blocs":["Quatre élèves doivent rédiger le règlement d’un tournoi. Ils ignorent à quelle équipe ils appartiendront, et s’ils seront les plus rapides ou les plus fragiles. Chacun propose une règle."],"source":"Situation écrite pour l’exercice, inspirée de Rawls"},{"id":"regles","type":"fiche","modele":"affiche","entete":"Quatre règles","sousTitre":"Règles écrites pour l’exercice","emoji":"🏆","teinte":"violet","lignes":[{"texte":"Les plus forts gagnent tout.","id":"z1"},{"texte":"Un léger avantage aux plus forts, à condition qu’il finance du matériel pour les plus fragiles.","id":"z2"},{"texte":"Le chef d’équipe choisit ce qu’il veut.","id":"z3"}],"pied":"Sous le voile d’ignorance"}],"questions":[{"enonce":"À quoi sert le voile d’ignorance ?","aide":"On ne sait pas quelle place on occupera.","type":"choix","options":[{"id":"a","texte":"À désigner à l’avance le gagnant du tournoi, sans tirage au sort"},{"id":"b","texte":"À supprimer toute règle pour laisser chacun jouer comme il l’entend"},{"id":"c","texte":"À cacher les règles du tournoi aux élèves jusqu’à la fin de la partie"},{"id":"d","texte":"À empêcher chacun de choisir les règles selon son intérêt personnel"}],"multiple":false},{"enonce":"Touche la règle inégalitaire que des personnes sous le voile d’ignorance accepteraient.","aide":"Une inégalité acceptable profite aux plus défavorisés.","type":"zone","document":"regles","multiple":false},{"enonce":"Remets dans l’ordre le raisonnement de Rawls.","aide":"On part de l’ignorance, on arrive au critère.","type":"ordre","items":[{"id":"a","texte":"On choisit les règles sans savoir si l’on sera favorisé ou défavorisé"},{"id":"b","texte":"On s’imagine ignorant de sa place dans la société"},{"id":"c","texte":"On refuse les règles qui écraseraient les plus défavorisés, car on pourrait en faire partie"},{"id":"d","texte":"On n’accepte que les inégalités qui profitent aux plus défavorisés"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["d"]},"explication":"Le voile d’ignorance met chacun à l’abri de son **intérêt personnel** : on choisit pour n’importe quelle place."},{"cle":{"type":"zone","ids":["z2"]},"explication":"C’est la règle **du léger avantage qui finance du matériel pour les plus fragiles** : elle profite aux plus défavorisés."},{"cle":{"type":"ordre","ids":["b","a","c","d"]},"explication":"Le raisonnement va de l’**ignorance de sa place** au critère final : les inégalités ne sont acceptables que si elles **profitent aux plus défavorisés**."}]$ex$::jsonb),
  ('f7d54ea5-7a57-5c35-8910-ef6e1fd05c7d'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Deux commerçants honnêtes","competence":"analyser-texte","situation":"Deux commerçants rendent la monnaie exacte, mais pas pour la même raison. Kant distingue agir conformément au devoir et agir par devoir.","documents":[{"id":"commercants","type":"texte","genre":"recit","titre":"Deux commerçants","blocs":["Amadou rend la monnaie exacte parce qu’il craint de perdre sa clientèle s’il triche. Bénédicte la rend exacte parce que tricher est injuste, même si personne ne le verrait."],"source":"Situation écrite pour l’exercice, dans l’esprit de Kant"}],"questions":[{"enonce":"Touche le mot qui montre que l’honnêteté d’Amadou est intéressée.","aide":"Il agit par peur de perdre quelque chose.","type":"zone","document":"commercants","multiple":false},{"enonce":"Range chaque motif : conformément au devoir, ou par devoir ?","aide":"L’acte est le même ; le mobile change.","type":"categories","categories":[{"id":"c0","texte":"Conformément au devoir"},{"id":"c1","texte":"Par devoir"}],"items":[{"id":"i0","texte":"Je dis vrai parce qu’il le faut, même sans témoin"},{"id":"i1","texte":"Je rends la monnaie pour ma réputation"},{"id":"i2","texte":"Je ne triche pas de peur d’être puni"},{"id":"i3","texte":"J’agis ainsi parce que c’est juste"}]},{"enonce":"Chez Kant, lequel des deux commerçants a une conduite moralement valable ?","aide":"Regarde le mobile, pas l’acte.","type":"choix","options":[{"id":"a","texte":"Amadou, parce qu’il rend la monnaie"},{"id":"b","texte":"Les deux, car l’acte est le même"},{"id":"c","texte":"Aucun, car il faut être pauvre"},{"id":"d","texte":"Bénédicte, parce qu’elle agit par devoir"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"C’est **craint** : Amadou est honnête par calcul, il agit conformément au devoir."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1"}},"explication":"L’acte est correct dans les deux cas, mais seul le motif du **respect de la loi morale** donne sa valeur morale à l’acte."},{"cle":{"type":"choix","ids":["d"]},"explication":"Seule **Bénédicte** agit par devoir : c’est le mobile qui donne sa valeur morale à l’acte."}]$ex$::jsonb),
  ('f7d54ea5-7a57-5c35-8910-ef6e1fd05c7d'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"L’impératif et son test","competence":"raisonner","situation":"Une affiche de conseils mélange deux sortes d’impératifs. Kant propose ensuite un test pour éprouver une maxime : celui de l’universalisation.","documents":[{"id":"conseils","type":"fiche","modele":"affiche","entete":"Six consignes","sousTitre":"Consignes écrites pour l’exercice","emoji":"📣","teinte":"ambre","lignes":[{"texte":"Si tu veux réussir ton bac, révise régulièrement.","id":"z1"},{"texte":"Ne mens pas.","id":"z2"},{"texte":"Si tu veux te faire des amis, sois généreux.","id":"z3"},{"texte":"Tiens ta promesse.","id":"z4"}],"pied":"Hypothétique ou catégorique ?"},{"id":"maxime","type":"texte","genre":"source","titre":"Une maxime à éprouver","blocs":["« Quand j’ai besoin d’argent, je ferai une fausse promesse de remboursement. »"],"source":"Maxime écrite pour l’exercice, à la manière de l’exemple de Kant"}],"questions":[{"enonce":"Range chaque consigne : impératif hypothétique ou catégorique ?","aide":"Y a-t-il un « si tu veux » ?","type":"categories","categories":[{"id":"c0","texte":"Hypothétique"},{"id":"c1","texte":"Catégorique"}],"items":[{"id":"i0","texte":"Si tu veux te faire des amis, sois généreux"},{"id":"i1","texte":"Si tu veux réussir ton bac, révise"},{"id":"i2","texte":"Tiens ta promesse"},{"id":"i3","texte":"Ne mens pas"}]},{"enonce":"Que se passerait-il si tout le monde suivait la maxime du document 2 ?","aide":"Imagine que tous font de fausses promesses.","type":"choix","options":[{"id":"a","texte":"Tout le monde serait riche, puisque chacun obtiendrait ce qu’il demande"},{"id":"b","texte":"Rien ne changerait, car chacun continuerait de croire aux promesses"},{"id":"c","texte":"La loi serait plus sévère, car il faudrait punir chaque promesse non tenue"},{"id":"d","texte":"Plus personne ne croirait aux promesses : la maxime se détruirait elle-même"}],"multiple":false},{"enonce":"Remets dans l’ordre les étapes du test d’universalisation.","aide":"On formule, on universalise, on vérifie, on conclut.","type":"ordre","items":[{"id":"a","texte":"Si elle se détruit, l’action est contraire au devoir"},{"id":"b","texte":"Vérifier qu’elle reste possible et voulable"},{"id":"c","texte":"Formuler la maxime de son action"},{"id":"d","texte":"L’imaginer devenue loi universelle"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1"}},"explication":"Un impératif **hypothétique** dépend d’un but (« si tu veux »), un **catégorique** commande sans condition."},{"cle":{"type":"choix","ids":["d"]},"explication":"Universalisée, la maxime rend **toute promesse incroyable**, donc elle se détruit elle-même : elle est contraire au devoir."},{"cle":{"type":"ordre","ids":["c","d","b","a"]},"explication":"Le test suit quatre temps : **formuler, universaliser, vérifier, conclure**."}]$ex$::jsonb),
