   $ex${"titre":"Dire la vérité à l’assassin ?","competence":"argumenter","situation":"Le cas de l’assassin à la porte oppose conviction et responsabilité. Tu confrontes la situation, l’objection de Constant et l’éthique de Max Weber.","documents":[{"id":"cas","type":"texte","genre":"source","titre":"Un homme à ta porte","blocs":["Un homme frappe à ta porte, une arme à la main, et demande où se cache ton ami."],"source":"Situation écrite pour l’exercice, inspirée de l’objection de Benjamin Constant"},{"id":"reponses","type":"fiche","modele":"affiche","entete":"Trois réponses possibles","sousTitre":"Réponses écrites pour l’exercice","emoji":"🚪","teinte":"corail","lignes":[{"texte":"Je dis la vérité, quoi qu’il arrive.","id":"z1"},{"texte":"Je mens, car il faut sauver mon ami et je juge d’après les effets.","id":"z2"},{"texte":"Je fais ce qui m’arrange, sans me soucier ni du principe ni des effets.","id":"z3"}],"pied":"Conviction, responsabilité ou cynisme ?"}],"questions":[{"enonce":"Associe chaque réponse à l’attitude qu’elle illustre.","aide":"Le principe, les effets, l’intérêt seul.","type":"association","gauche":[{"id":"g0","texte":"Je dis la vérité, quoi qu’il arrive"},{"id":"g1","texte":"Je mens pour sauver mon ami en jugeant d’après les effets"},{"id":"g2","texte":"Je fais ce qui m’arrange"}],"droite":[{"id":"d0","texte":"Éthique de responsabilité"},{"id":"d1","texte":"Cynisme"},{"id":"d2","texte":"Éthique de conviction"}]},{"enonce":"Touche la réponse que l’objection de Constant vise chez Kant.","aide":"Celle qui ne cède sur rien.","type":"zone","document":"reponses","multiple":false},{"enonce":"Que propose Max Weber en réponse à ce dilemme ?","aide":"Il ne choisit pas l’un contre l’autre.","type":"choix","options":[{"id":"a","texte":"Tenir ensemble la conviction et la responsabilité, sans jamais les confondre"},{"id":"b","texte":"Toujours mentir à l’assassin, quelles que soient les circonstances en jeu"},{"id":"c","texte":"Ignorer les conséquences de ses actes pour rester fidèle à ses principes"},{"id":"d","texte":"Renoncer à toute conviction pour ne juger que d’après les conséquences"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"Dire la vérité quoi qu’il arrive relève de la **conviction** ; juger d’après les effets, de la **responsabilité** ; ne plus rien viser que son intérêt, du **cynisme**."},{"cle":{"type":"zone","ids":["z1"]},"explication":"C’est la réponse de **la vérité quoi qu’il arrive** : Constant y voit une rigueur qui devient complice."},{"cle":{"type":"choix","ids":["a"]},"explication":"Pour Weber, un homme d’action sérieux tient **les deux sans les confondre** : renoncer à la conviction, c’est le cynisme ; ignorer les conséquences, l’irresponsabilité."}]$ex$::jsonb),
  ('8a83108a-1f1c-5b30-93cc-4e06e42a79e3'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Deux sens du mot « raison »","competence":"analyser-document","situation":"Quatre phrases emploient le mot « raison ». Tantôt c’est une faculté, tantôt une cause. Trie, repère, puis applique le principe de raison.","documents":[{"id":"phrases","type":"fiche","modele":"affiche","entete":"Quatre phrases","sousTitre":"Phrases écrites pour l’exercice","emoji":"💡","teinte":"ambre","lignes":[{"texte":"Après cette nuit blanche, il a presque perdu la raison.","id":"z1"},{"texte":"La raison de la chute, c’est la glace sur la route.","id":"z2"},{"texte":"La raison distingue l’homme de l’animal.","id":"z3"},{"texte":"Quelle est la raison de cet échec ?","id":"z4"}],"pied":"Faculté ou cause ?"}],"questions":[{"enonce":"Range chaque phrase selon le sens du mot « raison ».","aide":"Penser ou expliquer ?","type":"categories","categories":[{"id":"c0","texte":"La faculté de penser"},{"id":"c1","texte":"La cause d’une chose"}],"items":[{"id":"i0","texte":"Il a presque perdu la raison"},{"id":"i1","texte":"La raison distingue l’homme de l’animal"},{"id":"i2","texte":"Quelle est la raison de cet échec ?"},{"id":"i3","texte":"La raison de la chute, c’est la glace"}]},{"enonce":"Touche la phrase qui donne l’explication d’un fait.","aide":"On y trouve ce qui explique la chute.","type":"zone","document":"phrases","multiple":false},{"enonce":"Un voisin répond « c’est le hasard » à tout. Que demande le principe de raison ?","aide":"Rien n’arrive sans raison.","type":"choix","options":[{"id":"a","texte":"Chercher par quelle cause ou quelle raison l’événement s’explique"},{"id":"b","texte":"Interdire la question dès lors qu’aucune cause n’apparaît clairement"},{"id":"c","texte":"Accepter le hasard comme une explication suffisante et dernière"},{"id":"d","texte":"Croire au merveilleux dès que la cause n’est pas immédiatement connue"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1"}},"explication":"« Perdre la raison » et « distinguer l’homme » renvoient à la **faculté** ; « la raison de la chute » et « de cet échec », à la **cause**."},{"cle":{"type":"zone","ids":["z2"]},"explication":"C’est la phrase sur **la glace** : la raison est la cause du phénomène."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le principe de raison suffisante **interdit de se satisfaire du hasard** : il demande par quoi cela s’explique."}]$ex$::jsonb),
  ('8a83108a-1f1c-5b30-93cc-4e06e42a79e3'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Le soleil se lèvera-t-il demain ?","competence":"raisonner","situation":"Un texte adapté de Hume interroge l’idée de causalité. Tu le compares à la position de Descartes et tu testes ta compréhension.","documents":[{"id":"hume","type":"texte","genre":"source","titre":"Une boule qui en frappe une autre","blocs":["Je vois une boule en frapper une autre, puis la seconde rouler. Je ne vois jamais le lien nécessaire entre les deux. Je vois seulement l’une suivre l’autre, mille fois ; et c’est l’habitude qui me fait croire à un lien."],"source":"D’après Hume, *Enquête sur l’entendement humain* (1748) — texte adapté"},{"id":"comparaison","type":"tableau","titre":"Deux théories du savoir","colonnes":["","Rationalisme (Descartes)","Empirisme (Hume)"],"lignes":[["D’où vient le savoir","De la raison seule","De l’expérience"],["Le modèle","Les mathématiques","L’observation"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui explique, selon Hume, notre croyance à un lien de cause.","aide":"Un comportement qui se répète.","type":"zone","document":"hume","multiple":false},{"enonce":"Range chaque trait du côté de Descartes ou de Hume.","aide":"Raison seule ou expérience ?","type":"categories","categories":[{"id":"c0","texte":"Descartes"},{"id":"c1","texte":"Hume"}],"items":[{"id":"i0","texte":"Expérience répétée"},{"id":"i1","texte":"L’observation comme modèle"},{"id":"i2","texte":"Idées claires et distinctes"},{"id":"i3","texte":"Les mathématiques comme modèle"}]},{"enonce":"« Le soleil s’est toujours levé, donc il se lèvera nécessairement demain. » Que répondrait Hume ?","aide":"L’expérience montre ce qui a eu lieu, pas ce qui doit avoir lieu.","type":"choix","options":[{"id":"a","texte":"C’est une révélation divine, qui garantit la régularité de la nature"},{"id":"b","texte":"C’est une habitude née de l’expérience, pas une nécessité démontrée"},{"id":"c","texte":"C’est une vérité mathématique, démontrable par le seul raisonnement"},{"id":"d","texte":"C’est une erreur de calcul des astronomes, qui se sont trompés d’un jour"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m36"]},"explication":"C’est **habitude** : la causalité n’est pas un lien nécessaire connu, c’est une habitude née de l’expérience."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"**Descartes** : idées claires et mathématiques. **Hume** : expérience répétée et observation."},{"cle":{"type":"choix","ids":["b"]},"explication":"Hume répondrait que notre attente est une **habitude**, non la connaissance d’un lien nécessaire."}]$ex$::jsonb),
