   $ex${"titre":"Les Lumières et leur ombre","competence":"argumenter","situation":"Un texte adapté de Kant exalte la raison ; un logiciel imaginaire montre ce qui arrive quand elle ne fait que calculer. Tu construis ensuite un plan autour des limites de la raison.","documents":[{"id":"kant","type":"texte","genre":"source","titre":"Sortir de la minorité","blocs":["Les Lumières sont la sortie de l’homme de la minorité dont il est lui-même responsable. *Sapere aude !* Aie le courage de te servir de ton propre entendement."],"source":"D’après Kant, *Qu’est-ce que les Lumières ?* (1784) — texte adapté"},{"id":"logiciel","type":"texte","genre":"article","titre":"Le logiciel de la centrale de livraison","blocs":["Le logiciel de la société imaginaire Routex calcule le trajet le plus rapide de chaque camion. Il ne se demande jamais ce que les camions transportent, ni pourquoi."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux mots qui résument l’exigence des Lumières.","aide":"Un trait de caractère, et une faculté de penser.","type":"zone","document":"kant","multiple":true},{"enonce":"Que montre l’exemple du logiciel ?","aide":"Que ne demande-t-il jamais ?","type":"choix","options":[{"id":"a","texte":"Que les camions sont dangereux et que la technique devrait être arrêtée"},{"id":"b","texte":"Que Kant avait tort sur tous les points concernant l’usage de la raison"},{"id":"c","texte":"Une rationalité instrumentale : elle calcule les moyens sans interroger les fins"},{"id":"d","texte":"Que la raison est inutile pour décider, puisqu’elle ne mène qu’à des calculs"}],"multiple":false},{"enonce":"Associe chaque époque à ce que la raison y promet ou y montre.","aide":"Une promesse, puis un risque.","type":"association","gauche":[{"id":"g0","texte":"Les Lumières"},{"id":"g1","texte":"Le XXe siècle"}],"droite":[{"id":"d0","texte":"Une rationalité instrumentale qui peut servir le pire"},{"id":"d1","texte":"L’émancipation par le savoir"}]},{"enonce":"Organise un plan pour « La raison peut-elle tout expliquer ? ».","aide":"Thèse, limites, autre ordre.","type":"ordre","items":[{"id":"a","texte":"Mais la raison s’égare quand elle veut connaître ce qui dépasse l’expérience"},{"id":"b","texte":"Le principe de raison : rien n’arrive sans raison, tout s’explique"},{"id":"c","texte":"Pascal : un autre ordre que celui de la démonstration, sans renoncer à penser"}]}]}$ex$::jsonb,
