   $ex${"titre":"La pierre qui se croit libre","competence":"analyser-texte","situation":"Spinoza compare l’homme à une pierre lancée dans l’air. Un dialogue d’aujourd’hui illustre son idée.","documents":[{"id":"spinoza","type":"texte","genre":"lettre","titre":"La pierre et le désir","blocs":["Imagine une pierre lancée, qui croirait, pendant son vol, se mouvoir librement parce qu’elle sent son effort. Les hommes se croient libres de même : ils ont conscience de leurs désirs, mais ignorent les causes qui les déterminent."],"source":"D’après Spinoza, *Lettre à Schuller* — texte adapté"},{"id":"sms","type":"dialogue","modele":"sms","participants":[{"nom":"Lola","emoji":"👧","cote":"gauche"},{"nom":"Nils","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lola","texte":"J’ai acheté ces baskets, je les ai choisies librement, j’en avais envie !"},{"qui":"Nils","texte":"Elles étaient dans toutes les pubs en ce moment, non ?"}]}],"questions":[{"enonce":"Touche les deux mots qui expliquent l’illusion de la liberté.","aide":"Je sais ce que je désire, mais pas ce qui me détermine.","type":"zone","document":"spinoza","multiple":true},{"enonce":"Associe ce que je crois à ce qui se passe réellement.","aide":"Illusion d’un côté, détermination de l’autre.","type":"association","gauche":[{"id":"g0","texte":"Je choisis librement mon désir"},{"id":"g1","texte":"J’agis par ma volonté"},{"id":"g2","texte":"Mon goût est entièrement le mien"}],"droite":[{"id":"d0","texte":"Il a été façonné par la mode et la publicité"},{"id":"d1","texte":"J’ignore les causes qui m’ont déterminé"},{"id":"d2","texte":"Le désir m’est venu sans que je le décide"}]},{"enonce":"Que montre le dialogue de Lola et Nils ?","aide":"Regarde d’où vient l’envie.","type":"choix","options":[{"id":"a","texte":"Que Nils est libre de tout désir alors que Lola est esclave de la mode"},{"id":"b","texte":"Que Lola manque de goût et choisit toujours ses vêtements sans réfléchir"},{"id":"c","texte":"Que les baskets sont trop chères pour que Lola puisse vraiment les désirer"},{"id":"d","texte":"Que le désir de Lola vient de l’extérieur, sans qu’elle s’en rende compte"}],"multiple":false}]}$ex$::jsonb,
