[{"id":"a","texte":"Être libre, c’est devenir maître de ses désirs : la liberté est une conquête"},{"id":"b","texte":"Être libre, c’est ne rencontrer aucun obstacle"},{"id":"c","texte":"Mais faire ce que l’on veut est un caprice : les désirs viennent d’ailleurs, et autrui limite"}]}]}$ex$::jsonb,
