  ('ec09b321-34f9-5e16-88ea-7d5fcebe79ab'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Pile ou face, ou raisons ?","competence":"raisonner","situation":"Malo doit choisir un club pour l’an prochain. Observe comment il s’y prend, puis range les manières de choisir.","documents":[{"id":"malo","type":"texte","genre":"recit","titre":"Le choix de Malo","blocs":["Malo hésite entre le théâtre et le judo. Dimanche, il s’en remet au hasard : une pièce décidera, sans autre raison. Puis il se ravise. Il note ce qu’il attend de chaque activité, demande conseil à son frère et pèse le pour et le contre. Après une semaine, il choisit le théâtre en sachant pourquoi."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui dit comment Malo choisit la première fois.","aide":"Cherche ce qui décide à la place de Malo.","type":"zone","document":"malo","multiple":false},{"enonce":"Range ces manières de choisir.","aide":"Dans un cas rien ne guide le choix ; dans l’autre, des raisons le guident.","type":"categories","categories":[{"id":"c0","texte":"Liberté d’indifférence"},{"id":"c1","texte":"Liberté éclairée"}],"items":[{"id":"i0","texte":"Se renseigner avant de s’inscrire"},{"id":"i1","texte":"Tirer un nom au sort pour un exposé"},{"id":"i2","texte":"Peser les avantages et les inconvénients"},{"id":"i3","texte":"Trancher à pile ou face"}]},{"enonce":"Complète la conclusion.","aide":"Choisir en sachant pourquoi, c’est choisir en connaissance de quoi ?","type":"trous","segments":["Quand Malo compare les raisons, sa liberté ne diminue pas : elle augmente, car il choisit en connaissance de ",0," ."],"banque":["hasard","cause","fait","force"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14"]},"explication":"C’est le **hasard** : une pièce tranche, sans aucune raison."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0"}},"explication":"Choisir au **hasard**, c’est la liberté d’indifférence, le plus bas degré selon Descartes ; choisir après avoir réfléchi, c’est la liberté **éclairée**."},{"cle":{"type":"trous","trous":[["cause"]]},"affichage":"cause","explication":"Malo choisit en connaissance de **cause** : plus il a de raisons, plus il est libre."}]$ex$::jsonb),
  ('ec09b321-34f9-5e16-88ea-7d5fcebe79ab'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Quoi que je fasse ?","competence":"analyser-document","situation":"Deux amis discutent avant un examen. L’un est fataliste, l’autre pense que ses actes ont des causes. Distingue les deux positions.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Avant le bac blanc","participants":[{"nom":"Yanis","emoji":"👦","cote":"gauche"},{"nom":"Camille","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Yanis","texte":"Inutile de réviser : si je dois rater, je raterai, quoi que je fasse."},{"qui":"Camille","texte":"Moi je pense que mes notes ont des causes : mon travail, mon sommeil, mes cours."},{"qui":"Yanis","texte":"Donc tu n’as pas le choix ?"},{"qui":"Camille","texte":"Ce que je fais compte, même si mes choix ont des causes."}],"source":"Dialogue écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui résume la conséquence pratique du fatalisme.","aide":"Quel mot dit que l’effort ne sert à rien ?","type":"zone","document":"sms","multiple":false},{"enonce":"Range ces phrases selon la thèse qu’elles expriment.","aide":"Pose-toi la question : l’acte change-t-il quelque chose ?","type":"categories","categories":[{"id":"c0","texte":"Fatalisme"},{"id":"c1","texte":"Déterminisme"}],"items":[{"id":"i0","texte":"Mes actes ont des causes et sont des causes à leur tour"},{"id":"i1","texte":"Ce que je fais compte, même si tout a des causes"},{"id":"i2","texte":"Autant ne rien faire : rien ne changera"},{"id":"i3","texte":"Quoi que je fasse, l’avenir est écrit"}]},{"enonce":"Associe chaque penseur à l’idée qu’il défend.","aide":"Pense à la cause ignorée, à l’intelligence parfaite, au devoir, à la mauvaise foi.","type":"association","gauche":[{"id":"g0","texte":"Spinoza"},{"id":"g1","texte":"Laplace"},{"id":"g2","texte":"Kant"},{"id":"g3","texte":"Sartre"}],"droite":[{"id":"d0","texte":"Une intelligence connaissant toutes les forces saurait tout l’avenir"},{"id":"d1","texte":"Comme sujet moral, je dois me penser libre"},{"id":"d2","texte":"Nous nous croyons libres parce que nous ignorons les causes"},{"id":"d3","texte":"Invoquer ses déterminations est déjà un choix"}]},{"enonce":"Quelle position Camille défend-elle ?","aide":"Elle dit que ses actes ont des causes, et qu’ils comptent.","type":"choix","options":[{"id":"a","texte":"La liberté d’indifférence"},{"id":"b","texte":"Le fatalisme"},{"id":"c","texte":"Le relativisme"},{"id":"d","texte":"Le déterminisme, sans fatalisme"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0"]},"explication":"C’est **inutile** : le fataliste conclut que rien de ce qu’il fait ne change l’avenir."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"Le **fatalisme** nie l’effet de mes actes ; le **déterminisme** dit que mes actes ont des causes, mais ils sont à leur tour des causes."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2","g3":"d3"}},"explication":"**Spinoza** : l’ignorance des causes ; **Laplace** : l’intelligence qui prévoit tout ; **Kant** : la liberté comme exigence morale ; **Sartre** : la mauvaise foi."},{"cle":{"type":"choix","ids":["d"]},"explication":"Camille défend le **déterminisme sans fatalisme** : ses actes ont des causes et ce qu’elle fait compte."}]$ex$::jsonb),
  ('ec09b321-34f9-5e16-88ea-7d5fcebe79ab'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Sommes-nous libres de nos choix ?","competence":"argumenter","situation":"Tu prépares une dissertation sur le sujet de la fiche. Trie les arguments, choisis la problématique, puis construis le plan.","documents":[{"id":"sujet","type":"fiche","modele":"affiche","entete":"Sujet de dissertation","sousTitre":"Sujet donné pour l’exercice","emoji":"📝","teinte":"violet","lignes":[{"texte":"« Sommes-nous libres de nos choix ? »","id":"z1"}]},{"id":"eleves","type":"fiche","modele":"affiche","entete":"Quatre élèves, quatre positions","sousTitre":"Écrit pour l’exercice","emoji":"💬","teinte":"bleu","lignes":[{"texte":"Inès : « J’ai choisi mon vélo, donc je suis libre. »","id":"z2"},{"texte":"Noé : « Mon choix avait des causes, donc je n’ai rien choisi. »","id":"z3"},{"texte":"Lina : « Mes actes ont des causes, mais je dois agir comme si j’étais libre. »","id":"z4"},{"texte":"Adam : « Tout est écrit, je ne change rien. »","id":"z5"}]}],"questions":[{"enonce":"Trie ces arguments.","aide":"Deux arguments défendent la liberté, deux la ruinent.","type":"categories","categories":[{"id":"c0","texte":"Pour le libre arbitre"},{"id":"c1","texte":"Contre le libre arbitre"}],"items":[{"id":"i0","texte":"Sans libre arbitre, punir et féliciter n’aurait pas de sens"},{"id":"i1","texte":"Je sens que j’aurais pu choisir autrement"},{"id":"i2","texte":"Nous ignorons les causes qui nous déterminent"},{"id":"i3","texte":"Origine sociale et éducation conditionnent nos décisions"}]},{"enonce":"Quelle problématique convient au sujet de la fiche « Sujet » ?","aide":"Une problématique reprend le sujet et en montre la tension.","type":"choix","options":[{"id":"a","texte":"Faut-il punir les élèves qui trichent lorsqu’ils savent que la triche est interdite ?"},{"id":"b","texte":"Le déterminisme est-il une théorie scientifique vérifiée par toutes les disciplines ?"},{"id":"c","texte":"La liberté est-elle une bonne chose pour tous les hommes dans toutes les sociétés ?"},{"id":"d","texte":"Si tous nos choix ont des causes, peut-on dire que nous aurions pu choisir autrement ?"}],"multiple":false},{"enonce":"Remets dans l’ordre un plan en trois temps.","aide":"Thèse, antithèse, dépassement.","type":"ordre","items":[{"id":"a","texte":"Dépasser : choisir en connaissance de cause, ou se penser libre par devoir"},{"id":"b","texte":"On se sent libre : choisir, c’est pouvoir faire autrement"},{"id":"c","texte":"Mais tout a des causes : le déterminisme ruine cette impression"}]},{"enonce":"Touche l’élève dont la position rappelle celle de Kant.","aide":"Kant sépare le plan de la nature et celui du sujet moral.","type":"zone","document":"eleves","multiple":false},{"enonce":"Touche l’élève qui confond déterminisme et fatalisme.","aide":"Lequel dit que ses actes ne changent rien ?","type":"zone","document":"eleves","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1"}},"explication":"Le **sentiment** de liberté et la **responsabilité** plaident pour ; le **conditionnement** et l’**ignorance des causes** plaident contre."},{"cle":{"type":"choix","ids":["d"]},"explication":"La bonne problématique met face à face la **liberté** et la **causalité** ; les autres sont hors sujet ou à côté."},{"cle":{"type":"ordre","ids":["b","c","a"]},"explication":"Le plan va de la **thèse** (on se sent libre) à l’**antithèse** (tout a des causes) puis au **dépassement**."},{"cle":{"type":"zone","ids":["z4"]},"explication":"C’est **Lina** : comme phénomène, elle est soumise aux causes ; comme sujet moral, elle doit se penser libre."},{"cle":{"type":"zone","ids":["z5"]},"explication":"C’est **Adam** : « tout est écrit, je ne change rien » est du fatalisme, non du déterminisme."}]$ex$::jsonb),
