   $ex${"titre":"La règle de la classe","competence":"analyser-texte","situation":"Deux classes, deux manières de fixer une règle. Regarde d’où vient la règle, pas combien il y en a.","documents":[{"id":"classe","type":"texte","genre":"recit","titre":"Deux règlements","blocs":["Dans la classe de 2de B, le règlement est voté par tous les élèves. Zoé le trouve contraignant, mais elle l’a votée elle-même : obéir à une règle qu’on s’est donnée n’est pas obéir à un maître. Dans la classe voisine, le règlement est imposé par un délégué, sans consultation : les élèves se sentent soumis."],"source":"Texte écrit pour l’exercice, dans l’esprit de Rousseau"}],"questions":[{"enonce":"Touche le mot qui montre pourquoi Zoé reste libre en obéissant.","aide":"Elle a participé à la décision.","type":"zone","document":"classe","multiple":false},{"enonce":"Touche le mot qui décrit les élèves de la classe voisine.","aide":"Leur règle leur vient d’un seul.","type":"zone","document":"classe","multiple":false},{"enonce":"Complète.","aide":"Pense à Rousseau : qui fait la loi ?","type":"trous","segments":["La règle est libératrice quand elle exprime la volonté ",0," ; sans règle, ce n’est pas la liberté qui règne, c’est la ",1," ."],"banque":["particulière","force","générale","justice"]}]}$ex$::jsonb,
