   $ex${"titre":"Deux lycées, deux libertés","competence":"analyser-document","situation":"Deux lycées imaginaires illustrent deux modèles de liberté. Repère ce que chacun garantit et ce qu’il coûte.","documents":[{"id":"lycees","type":"texte","genre":"recit","titre":"Lycée A, lycée B","blocs":["Au lycée A, tous les élèves se réunissent en assemblée pour décider de tout, des horaires au menu ; personne ne peut s’y soustraire, et l’assemblée règle aussi les sorties et les fréquentations.","Au lycée B, chacun est libre de ses loisirs, de ses amitiés et de ses opinions ; mais le conseil des élèves ne réunit que 4 % des votants."],"source":"Texte écrit pour l’exercice, d’après la distinction de Benjamin Constant"}],"questions":[{"enonce":"Range ces traits.","aide":"Participer à tout, ou jouir de son indépendance privée.","type":"categories","categories":[{"id":"c0","texte":"Liberté des Anciens"},{"id":"c1","texte":"Liberté des Modernes"}],"items":[{"id":"i0","texte":"Se désintéresser des affaires publiques"},{"id":"i1","texte":"Choisir ses amis et ses opinions sans rendre de comptes"},{"id":"i2","texte":"Décider directement en assemblée"},{"id":"i3","texte":"Être entièrement soumis à la cité"}]},{"enonce":"Touche le chiffre qui révèle le risque de la liberté du lycée B.","aide":"Quel chiffre dit que peu de monde participe ?","type":"zone","document":"lycees","multiple":false},{"enonce":"Quelle conclusion le cours en tire-t-il ?","aide":"Aucun des deux lycées n’est un modèle complet.","type":"choix","options":[{"id":"a","texte":"Une démocratie sérieuse tient les deux libertés sans sacrifier l’une à l’autre"},{"id":"b","texte":"Il faut revenir à la seule liberté des Anciens, fondée sur la participation"},{"id":"c","texte":"Il faut abandonner la participation politique et ne garder que la vie privée"},{"id":"d","texte":"Seule la liberté privée compte, et l’État doit s’effacer devant les individus"}],"multiple":false}]}$ex$::jsonb,
