iée ?","aide":"Quelle est la seule raison de contraindre quelqu’un ?","type":"choix","options":[{"id":"a","texte":"Oui : ses idées sont déplaisantes"},{"id":"b","texte":"Oui : la majorité a toujours raison"},{"id":"c","texte":"Oui : le club est minoritaire"},{"id":"d","texte":"Non : le club ne nuit à personne"}],"multiple":false},{"enonce":"Quels comportements relèvent de la désobéissance civile ?","aide":"Elle est publique, non violente, et assume la sanction.","type":"categories","categories":[{"id":"c0","texte":"Désobéissance civile"},{"id":"c1","texte":"Pas de la désobéissance civile"}],"items":[{"id":"i0","texte":"Incendier une mairie de nuit"},{"id":"i1","texte":"Falsifier discrètement un document officiel"},{"id":"i2","texte":"Refuser publiquement une taxe jugée illégale et accepter d’être jugé"},{"id":"i3","texte":"Protester publiquement sans violence et assumer la sanction"}]}]}$ex$::jsonb,
