   $ex${"titre":"Dire, c’est faire","competence":"analyser-document","situation":"Six phrases entendues dans la journée. Certaines décrivent, d’autres agissent.","documents":[{"id":"phrases","type":"fiche","modele":"affiche","entete":"Six phrases entendues","sousTitre":"Phrases écrites pour l’exercice","emoji":"🗣️","teinte":"turquoise","lignes":[{"texte":"Le train part à 8 h 12.","id":"z1"},{"texte":"Je te promets de venir samedi.","id":"z2"},{"texte":"Il pleut depuis ce matin.","id":"z3"},{"texte":"Je m’excuse pour mon retard.","id":"z4"},{"texte":"La séance est ouverte.","id":"z5"},{"texte":"Paris est la capitale de la France.","id":"z6"}]}],"questions":[{"enonce":"Range ces énoncés.","aide":"Teste : puis-je dire « c’est vrai » ou « c’est faux » ?","type":"categories","categories":[{"id":"c0","texte":"Constatif"},{"id":"c1","texte":"Performatif"}],"items":[{"id":"i0","texte":"La séance est ouverte"},{"id":"i1","texte":"Il pleut depuis ce matin"},{"id":"i2","texte":"Je te promets de venir samedi"},{"id":"i3","texte":"Je m’excuse pour mon retard"},{"id":"i4","texte":"Paris est la capitale de la France"},{"id":"i5","texte":"Le train part à 8 h 12"}]},{"enonce":"Pourquoi « Il pleut » peut-il être faux, alors que « Je te promets » ne l’est pas ?","aide":"Décrire un fait ou accomplir un acte ?","type":"choix","options":[{"id":"a","texte":"Il décrit un fait, donc vrai ou faux ; la promesse fait quelque chose"},{"id":"b","texte":"La promesse est toujours sincère, donc elle ne peut jamais être fausse"},{"id":"c","texte":"Il pleut est un énoncé ancien, alors qu’une promesse est un énoncé récent"},{"id":"d","texte":"La promesse est une question, et une question n’est ni vraie ni fausse"}],"multiple":false},{"enonce":"Quel adjectif Austin emploie-t-il pour les énoncés qui font ce qu’ils disent ?","aide":"Il vient du verbe anglais qui veut dire « accomplir ».","type":"texte"}]}$ex$::jsonb,
