  ('8db367be-d98a-518c-8116-d39e8f5f129d'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le langage trahit-il la pensée ?","competence":"argumenter","situation":"Deux élèves défendent deux thèses opposées sur le lien entre mots et pensée. Compare-les, puis construis une problématique.","documents":[{"id":"theses","type":"texte","genre":"source","titre":"Deux élèves, deux thèses","blocs":["Sans mots, ma pensée reste une brume : c’est en la disant que je sais ce que je pense.","Dès que je dis « tristesse », j’écrase la nuance de ce que je ressens : le mot est commun à tous, mon émotion est unique."],"source":"Textes écrits pour l’exercice, dans l’esprit de Hegel et de Bergson"}],"questions":[{"enonce":"Associe chaque thèse à son penseur.","aide":"Quatre auteurs du chapitre, quatre idées.","type":"association","gauche":[{"id":"g0","texte":"Le mot donne à la pensée son existence"},{"id":"g1","texte":"Le mot commun écrase la nuance du vécu"},{"id":"g2","texte":"Le signe est arbitraire"},{"id":"g3","texte":"Un énoncé peut faire ce qu’il dit"}],"droite":[{"id":"d0","texte":"Austin"},{"id":"d1","texte":"Hegel"},{"id":"d2","texte":"Bergson"},{"id":"d3","texte":"Saussure"}]},{"enonce":"Touche le mot qui dit ce qu’est la pensée sans langage dans le premier texte.","aide":"Un état flou, sans contours.","type":"zone","document":"theses","multiple":false},{"enonce":"Pourquoi le second texte reproche-t-il au mot « tristesse » d’écraser la nuance ?","aide":"Le mot est pour tous, l’émotion pour moi.","type":"choix","options":[{"id":"a","texte":"Parce que le mot est arbitraire, donc choisi au hasard par chaque locuteur"},{"id":"b","texte":"Parce que le mot, commun à tous, ne peut dire ce que mon émotion a d’unique"},{"id":"c","texte":"Parce que le mot est toujours faux et ne désigne jamais rien de réel"},{"id":"d","texte":"Parce que le mot empêche de penser, même à celui qui ne l’emploie pas"}],"multiple":false},{"enonce":"Sujet : « Le langage trahit-il la pensée ? » Quelle démarche tient les deux thèses ?","aide":"Une dissertation ne tranche pas trop vite.","type":"choix","options":[{"id":"a","texte":"Non, puis oui, puis non, en enchaînant les thèses sans aucun lien entre elles"},{"id":"b","texte":"Le langage est arbitraire, donc il ne trahit rien et ne rend rien possible"},{"id":"c","texte":"Hegel a raison sur toute la ligne, Bergson a tort, et la question est close"},{"id":"d","texte":"Le langage rend la pensée possible mais la trahit : il faut tenir cette tension"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g1":"d2","g2":"d3"}},"explication":"**Hegel** : la pensée existe dans le mot ; **Bergson** : le mot écrase le vécu ; **Saussure** : le signe est arbitraire ; **Austin** : les performatifs."},{"cle":{"type":"zone","ids":["m6"]},"explication":"C’est **brume** : la pensée sans mots reste informe."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le mot est **commun à tous** ; il ne peut dire ce que le vécu a de **singulier**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le langage rend la pensée possible **et** la trahit : c’est cette **tension** qu’il faut tenir."}]$ex$::jsonb),
