  ('36834bd6-7806-517b-9ff1-2ce9ee56f042'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Dans la caverne","competence":"analyser-texte","situation":"Un récit adapté de l’allégorie de Platon. Repère ce qui trompe les prisonniers, puis l’accueil du vrai.","documents":[{"id":"caverne","type":"texte","genre":"recit","titre":"L’allégorie de la caverne","blocs":["Des prisonniers, enchaînés depuis l’enfance, ne voient sur le mur que des ombres d’objets portés derrière eux. Ils les nomment et pensent qu’elles sont la réalité. Un prisonnier est libéré ; ébloui, il sort, découvre le soleil et les vrais objets. De retour, il annonce aux autres qu’ils se trompent. Ils ne le croient pas et le raillent."],"source":"D’après Platon, *La République*, livre VII — texte adapté"}],"questions":[{"enonce":"Touche ce que les prisonniers prennent pour la réalité.","aide":"Ce qu’ils voient sur le mur.","type":"zone","document":"caverne","multiple":false},{"enonce":"Remets le récit dans l’ordre.","aide":"On suit le déplacement du prisonnier.","type":"ordre","items":[{"id":"a","texte":"L’un d’eux est libéré et découvre les vrais objets"},{"id":"b","texte":"Ils ne le croient pas et se moquent de lui"},{"id":"c","texte":"Des prisonniers ne voient que des ombres"},{"id":"d","texte":"Il revient annoncer aux autres qu’ils se trompent"}]},{"enonce":"Touche le mot qui montre comment les autres accueillent la vérité.","aide":"Ils ne le prennent pas au sérieux.","type":"zone","document":"caverne","multiple":false},{"enonce":"Quel épisode du cours rappelle l’accueil réservé à celui qui dit le vrai ?","aide":"Un philosophe jugé par sa cité.","type":"choix","options":[{"id":"a","texte":"Le cogito"},{"id":"b","texte":"La réfutation de Protagoras"},{"id":"c","texte":"Le procès de Socrate"},{"id":"d","texte":"Le pari de Pascal"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m13"]},"explication":"Ce sont les **ombres**."},{"cle":{"type":"ordre","ids":["c","a","d","b"]},"explication":"Les prisonniers voient des ombres, l’un se libère, revient, et n’est pas cru."},{"cle":{"type":"zone","ids":["m60"]},"explication":"C’est **raillent** : dire le vrai dérange."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le **procès de Socrate** : la vérité dérange les intérêts établis."}]$ex$::jsonb),
