   $ex${"titre":"Les haricots de Nina","competence":"experimenter","situation":"Nina observe ses plantes et teste une idée. Retrouve les temps de sa démarche.","documents":[{"id":"nina","type":"texte","genre":"recit","titre":"L’expérience de Nina","blocs":["Nina remarque que ses haricots poussent plus vite près de la fenêtre. Elle suppose que la lumière en est la cause. Elle place deux pots identiques, l’un au soleil, l’autre à l’ombre, avec la même eau et la même terre, et mesure la hauteur chaque jour."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Remets les étapes de la démarche dans l’ordre.","aide":"Observation, hypothèse, expérience.","type":"ordre","items":[{"id":"a","texte":"Elle compare deux pots, l’un au soleil, l’autre à l’ombre"},{"id":"b","texte":"Elle suppose que la lumière en est la cause"},{"id":"c","texte":"Elle remarque que les haricots près de la fenêtre poussent plus vite"}]},{"enonce":"Touche le verbe qui annonce l’hypothèse.","aide":"Un verbe qui dit « elle avance une réponse ».","type":"zone","document":"nina","multiple":false},{"enonce":"Pourquoi Nina garde-t-elle la même eau et la même terre ?","aide":"Que doit-il rester de différent entre les deux pots ?","type":"choix","options":[{"id":"a","texte":"Pour que seule la lumière change et que la différence lui soit attribuée"},{"id":"b","texte":"Parce que c’est plus simple à organiser et que cela évite d’acheter du matériel"},{"id":"c","texte":"Pour économiser l’eau et la terre, qui coûtent cher à renouveler"},{"id":"d","texte":"Pour que les deux pots poussent exactement pareil, quelle que soit la lumière"}],"multiple":false}]}$ex$::jsonb,
