  ('8922c185-ca43-55a7-bc0c-6505750bd2b8'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Nu et démuni","competence":"analyser-texte","situation":"Un récit adapté du mythe de Prométhée : comment l’homme survit-il ?","documents":[{"id":"mythe","type":"texte","genre":"recit","titre":"Le partage des qualités","blocs":["Quand vint l’heure de distribuer les qualités, Épiméthée donna aux animaux griffes, fourrure, vitesse et ailes. Il ne resta plus rien pour l’homme, qui sortit nu, sans défense. Prométhée, pris de pitié, déroba aux dieux le feu et le savoir des métiers : grâce à eux, l’homme put se vêtir, bâtir et se nourrir."],"source":"D’après Platon, *Protagoras* — texte adapté"}],"questions":[{"enonce":"Touche le mot qui dit le défaut originel de l’homme.","aide":"Il n’a ni fourrure ni griffes.","type":"zone","document":"mythe","multiple":false},{"enonce":"Touche ce que Prométhée dérobe aux dieux.","aide":"C’est ce qui permet de se chauffer et de forger.","type":"zone","document":"mythe","multiple":false},{"enonce":"Que dit ce mythe de la technique ?","aide":"Sans elle, l’homme ne survit pas.","type":"choix","options":[{"id":"a","texte":"Qu’elle est un don de la science, apparu bien après les premiers hommes"},{"id":"b","texte":"Qu’elle est une punition infligée aux hommes par les dieux"},{"id":"c","texte":"Qu’elle est la condition même de la survie d’un être nu et démuni"},{"id":"d","texte":"Qu’elle est un luxe réservé aux hommes qui ont le temps de penser"}],"multiple":false},{"enonce":"Remets le récit dans l’ordre.","aide":"Distribution, manque, vol, survie.","type":"ordre","items":[{"id":"a","texte":"Il ne reste plus rien pour l’homme, qui naît nu"},{"id":"b","texte":"Grâce à la technique, l’homme peut survivre"},{"id":"c","texte":"Prométhée dérobe aux dieux le feu et les métiers"},{"id":"d","texte":"Épiméthée distribue griffes, fourrure et ailes aux animaux"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m27"]},"explication":"C’est **nu** : l’homme naît sans défense."},{"cle":{"type":"zone","ids":["m38"]},"explication":"C’est le **feu**, avec le savoir des métiers."},{"cle":{"type":"choix","ids":["c"]},"explication":"La technique n’est pas un luxe : elle **compense** un défaut originel."},{"cle":{"type":"ordre","ids":["d","a","c","b"]},"explication":"Le récit va du **manque** à la **survie** par la technique."}]$ex$::jsonb),
  ('8922c185-ca43-55a7-bc0c-6505750bd2b8'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Qui commande ?","competence":"argumenter","situation":"Dans une entreprise imaginaire, un logiciel règle tout. Retrouve les penseurs qui éclairent la scène.","documents":[{"id":"logi","type":"texte","genre":"recit","titre":"Le logiciel de la logistique","blocs":["Dans une entreprise de livraison, un logiciel calcule le trajet de chaque livreur, à la minute. Personne n’a décidé d’aller toujours plus vite : le système l’exige, chaque amélioration appelle la suivante. Les livreurs deviennent des ressources à optimiser. Nul ne se demande si ces cadences seront compatibles avec une vie authentiquement humaine pour les générations futures."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Associe chaque phrase du texte au penseur qu’elle évoque.","aide":"Système, stock disponible, responsabilité.","type":"association","gauche":[{"id":"g0","texte":"Personne n’a décidé d’aller plus vite : le système l’exige"},{"id":"g1","texte":"Les livreurs deviennent des ressources à optimiser"},{"id":"g2","texte":"Nul ne se demande si c’est compatible avec une vie humaine pour les générations futures"}],"droite":[{"id":"d0","texte":"Hans Jonas"},{"id":"d1","texte":"Jacques Ellul"},{"id":"d2","texte":"Heidegger"}]},{"enonce":"Touche le mot qui traduit le regard décrit par Heidegger.","aide":"Le regard qui traite tout comme un stock.","type":"zone","document":"logi","multiple":false},{"enonce":"Le logiciel permet d’aller plus vite. En déduit-on qu’il faut l’installer partout ?","aide":"Pouvoir n’est pas devoir.","type":"choix","options":[{"id":"a","texte":"Oui : toute technique efficace est bonne et doit donc être employée partout"},{"id":"b","texte":"Non : les logiciels sont dangereux par nature, donc il faut les interdire"},{"id":"c","texte":"Oui : la technique est neutre, donc son installation n’appelle aucune réflexion"},{"id":"d","texte":"Non : ce que nous pouvons faire ne dit pas ce que nous devons faire"}],"multiple":false},{"enonce":"Remets un plan de dissertation sur « La technique nous libère-t-elle ? ».","aide":"Thèse, antithèse, dépassement.","type":"ordre","items":[{"id":"a","texte":"Mais un système technicien échappe à nos décisions (Ellul, Heidegger)"},{"id":"b","texte":"La technique compense nos manques (Prométhée)"},{"id":"c","texte":"Reste à la gouverner par la responsabilité (Jonas)"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"**Ellul** : système technicien ; **Heidegger** : tout devient stock disponible ; **Jonas** : responsabilité envers les générations futures."},{"cle":{"type":"zone","ids":["m38"]},"explication":"C’est **ressources** : tout est traité comme un stock disponible."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le **pouvoir** technique ne dit pas le **devoir**."},{"cle":{"type":"ordre","ids":["b","a","c"]},"explication":"On passe de la **libération** au **risque de servitude**, puis à la **responsabilité**."}]$ex$::jsonb),
