   $ex${"titre":"Agréable, bon ou beau ?","competence":"analyser-document","situation":"Trois jugements de la vie courante. Distingue-les comme Kant.","documents":[{"id":"juge","type":"fiche","modele":"affiche","entete":"Trois phrases","sousTitre":"Écrites pour l’exercice","emoji":"🎨","teinte":"rose","lignes":[{"texte":"« J’adore cette glace à la fraise. »","id":"z1"},{"texte":"« Ce geste est bon : il aide un voisin. »","id":"z2"},{"texte":"« Ce coucher de soleil est beau, et chacun devrait l’admirer. »","id":"z3"}]}],"questions":[{"enonce":"Touche la phrase qui prétend à l’accord des autres, sans passer par un concept.","aide":"Un goût qui exige un accord.","type":"zone","document":"juge","multiple":false},{"enonce":"Range ces jugements.","aide":"Plaît aux sens, par un concept, ou universellement sans concept.","type":"categories","categories":[{"id":"c0","texte":"Agréable"},{"id":"c1","texte":"Bon"},{"id":"c2","texte":"Beau"}],"items":[{"id":"i0","texte":"Ce canapé est très agréable"},{"id":"i1","texte":"Il est bon d’aider un voisin"},{"id":"i2","texte":"Ce plat me plaît"},{"id":"i3","texte":"Cette musique est belle, tout le monde devrait l’entendre"}]},{"enonce":"Complète.","aide":"Pas d’intérêt, mais une exigence.","type":"trous","segments":["Le jugement de goût est ",0," : je ne veux ni posséder ni consommer l’objet ; et pourtant il exige l’accord des ",1," ."],"banque":["sens","intéressé","autres","désintéressé"]}]}$ex$::jsonb,
