  ('3f486caa-bf4f-5818-aa58-17f56f064407'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"L’artisan et l’artiste","competence":"raisonner","situation":"Deux portraits imaginaires. Distingue celui qui applique une règle de celui qui la donne.","documents":[{"id":"portraits","type":"texte","genre":"recit","titre":"Jo et Maya","blocs":["Jo, menuisier, dessine d’abord le plan de la chaise, en fabrique dix identiques, et sait à l’avance le résultat.","Maya, peintre, commence une toile sans savoir où elle ira : c’est en peignant qu’elle découvre ce qu’elle cherche. Aucune recette ne lui permettrait de la refaire."],"source":"Portraits écrits pour l’exercice"}],"questions":[{"enonce":"Range ces traits.","aide":"Appliquer une règle ou la donner.","type":"categories","categories":[{"id":"c0","texte":"Artisan"},{"id":"c1","texte":"Artiste"}],"items":[{"id":"i0","texte":"Découvre l’œuvre en la faisant"},{"id":"i1","texte":"Peut refaire à l’identique"},{"id":"i2","texte":"Sait d’avance ce qu’il fabrique"},{"id":"i3","texte":"Donne la règle à son art"}]},{"enonce":"Touche ce que Jo établit avant de commencer.","aide":"Un dessin préalable.","type":"zone","document":"portraits","multiple":false},{"enonce":"Selon Walter Benjamin, que perd un tableau reproduit à un million d’exemplaires ?","aide":"Le hic et nunc.","type":"choix","options":[{"id":"a","texte":"Ses couleurs"},{"id":"b","texte":"Son aura"},{"id":"c","texte":"Son prix"},{"id":"d","texte":"Sa signification"}],"multiple":false},{"enonce":"Associe chaque penseur à son idée.","aide":"Quatre philosophes, quatre idées.","type":"association","gauche":[{"id":"g0","texte":"Platon"},{"id":"g1","texte":"Aristote"},{"id":"g2","texte":"Hegel"},{"id":"g3","texte":"Kant"}],"droite":[{"id":"d0","texte":"Le génie donne ses règles à l’art"},{"id":"d1","texte":"La tragédie opère une catharsis"},{"id":"d2","texte":"L’art est imitation d’imitation"},{"id":"d3","texte":"L’art présente sensiblement la vérité"}]}]}$ex$::jsonb,
