   $ex${"titre":"Faut-il que l’art plaise ?","competence":"argumenter","situation":"Devant une installation, deux élèves s’opposent. Retrouve l’idée du cours, puis bâtis la réflexion.","documents":[{"id":"musee","type":"texte","genre":"recit","titre":"Au musée","blocs":["Une classe visite un musée. Devant une installation de fils noirs tendus dans une pièce vide, Lou dit : « Je n’aime pas ça, donc ce n’est pas de l’art. » Ilan répond : « Ça me dérange, mais je ne peux pas l’oublier : ça compte. »"],"source":"Scène écrite pour l’exercice"}],"questions":[{"enonce":"Quelle idée du cours Ilan illustre-t-il ?","aide":"Il est dérangé et pourtant touché.","type":"choix","options":[{"id":"a","texte":"Une œuvre doit plaire pour avoir de la valeur"},{"id":"b","texte":"L’art est une imitation"},{"id":"c","texte":"L’art est un marché"},{"id":"d","texte":"Une œuvre peut déplaire et compter"}],"multiple":false},{"enonce":"Touche le verbe qui fait de l’art une affaire de plaisir personnel.","aide":"Le critère de Lou est son goût.","type":"zone","document":"musee","multiple":false},{"enonce":"Remets le plan sur « L’art doit-il plaire ? ».","aide":"Thèse, antithèse, dépassement.","type":"ordre","items":[{"id":"a","texte":"Mais certaines œuvres déplaisent et comptent"},{"id":"b","texte":"L’art se distingue du divertissement"},{"id":"c","texte":"Une œuvre doit plaire pour avoir de la valeur"}]},{"enonce":"Quelle problématique convient à « L’art doit-il plaire ? » ?","aide":"Elle doit faire apparaître la tension du sujet.","type":"choix","options":[{"id":"a","texte":"Si une œuvre peut déplaire et compter, en quoi sa valeur ne se réduit-elle pas au plaisir ?"},{"id":"b","texte":"Faut-il interdire l’art contemporain, puisqu’une partie du public ne l’apprécie pas ?"},{"id":"c","texte":"Quels artistes plaisent le plus au public, et comment mesure-t-on leur succès ?"},{"id":"d","texte":"Qui achète les œuvres d’art, et à quel prix les vend-on aujourd’hui sur le marché ?"}],"multiple":false}]}$ex$::jsonb,
