   $ex${"titre":"Que faire du temps qui passe ?","competence":"argumenter","situation":"Trois devises, une promesse, un plan : comment habiter le temps ?","documents":[{"id":"devises","type":"fiche","modele":"affiche","entete":"Trois devises","sousTitre":"Formules résumées pour l’exercice","emoji":"⏳","teinte":"ambre","lignes":[{"texte":"Épicure : tant que nous sommes, la mort n’est pas là ; quand elle est là, nous ne sommes plus.","id":"z1"},{"texte":"Sénèque : nous ne manquons pas de temps, nous en perdons beaucoup.","id":"z2"},{"texte":"Horace : *carpe diem*, cueille le jour.","id":"z3"}]}],"questions":[{"enonce":"Touche la devise qui convient à quelqu’un qui se plaint de manquer de temps mais passe des heures sur son téléphone.","aide":"Il ne manque pas de temps, il le perd.","type":"zone","document":"devises","multiple":false},{"enonce":"Touche la devise qui convient à quelqu’un qui craint la mort.","aide":"Une phrase qui dissout la crainte.","type":"zone","document":"devises","multiple":false},{"enonce":"Promettre quelque chose à un ami suppose-t-il un temps réversible ?","aide":"Que rend possible l’irréversibilité ?","type":"choix","options":[{"id":"a","texte":"Non : c’est justement parce que le temps passe qu’un acte engage"},{"id":"b","texte":"Oui : sinon la promesse est fausse dès qu’elle est prononcée"},{"id":"c","texte":"Oui : il faut pouvoir revenir en arrière pour tenir sa parole"},{"id":"d","texte":"Non : promettre ne concerne en rien le temps ni l’avenir"}],"multiple":false},{"enonce":"Remets un plan sur « Le temps est-il notre ennemi ? ».","aide":"Thèse, antithèse, dépassement.","type":"ordre","items":[{"id":"a","texte":"L’art d’y vivre : ne pas perdre son temps, cueillir le jour"},{"id":"b","texte":"Il nous enlève : vieillissement, regret, mort"},{"id":"c","texte":"Mais il rend possibles projet, promesse et histoire"}]},{"enonce":"Sujet : « Le temps est-il notre ennemi ? » Quelle problématique convient ?","aide":"Elle doit faire apparaître la tension du sujet.","type":"choix","options":[{"id":"a","texte":"Quelle heure est-il, et comment mesure-t-on le temps avec précision ?"},{"id":"b","texte":"Faut-il ne plus vieillir, et comment y parvenir grâce à la médecine ?"},{"id":"c","texte":"Qui a inventé l’horloge, et à quelle époque est-elle devenue courante ?"},{"id":"d","texte":"Si le temps nous enlève tout, comment rend-il aussi possibles nos projets ?"}],"multiple":false}]}$ex$::jsonb,
