  ('8561efa6-7303-530e-a51d-a4b84b1ef822'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Deux façons de répartir les points","competence":"calculer","situation":"Zoé et Hugo ont passé la même épreuve, mais ils n’ont pas choisi la même répartition des 8 points entre l’AFL2 et l’AFL3. L’AFL1 est noté sur 12 pour tout le monde.","documents":[{"id":"bareme","type":"tableau","titre":"Les points de Zoé et de Hugo","colonnes":["Élève","AFL1","AFL2","AFL3","Total"],"lignes":[["Zoé","10 sur 12","3 sur 4","2 sur 4","?"],["Hugo","8 sur 12","5 sur 6","2 sur 2","?"]],"enteteLignes":true,"source":"Notes écrites pour l’exercice"}],"questions":[{"enonce":"Quel est le total de Zoé sur 20 ?","aide":"Additionne ses points obtenus : 10, 3 et 2.","type":"nombre","unite":"points"},{"enonce":"Quel est le total de Hugo sur 20 ?","aide":"Additionne ses points obtenus : 8, 5 et 2.","type":"nombre","unite":"points"},{"enonce":"Laquelle de ces phrases décrit le choix de Hugo ?","aide":"Regarde les « sur … » dans les colonnes AFL2 et AFL3.","type":"choix","options":[{"id":"a","texte":"Il a équilibré ses points : 4 points pour l’AFL2 et 4 pour l’AFL3"},{"id":"b","texte":"Il a donné la priorité aux rôles : 2 points pour l’AFL2 et 6 pour l’AFL3"},{"id":"c","texte":"Il a donné la priorité à l’entraînement : 6 points pour l’AFL2 et 2 pour l’AFL3"},{"id":"d","texte":"Il a tout misé sur les rôles : 0 point pour l’AFL2 et 8 pour l’AFL3"}],"multiple":false},{"enonce":"Si Hugo avait obtenu seulement 1 sur 2 à l’AFL3, quel aurait été son total ?","aide":"Remplace 2 par 1 dans son total.","type":"nombre","unite":"points"}]}$ex$::jsonb,
