  ('8561efa6-7303-530e-a51d-a4b84b1ef822'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Que prévoit le règlement ?","competence":"analyser-document","situation":"Trois élèves de Terminale se trouvent dans des situations différentes face au bac d’EPS. Le règlement prévoit pour chacune une conséquence précise. Un tableau donne les notes de Sacha.","documents":[{"id":"cas","type":"texte","genre":"article","titre":"Trois situations","auteur":"Texte écrit pour l’exercice","blocs":["**Sacha** était absent à son épreuve de natation et n’a fourni aucun justificatif.","**Lola** s’est blessée à la cheville une semaine avant son épreuve ; son certificat médical l’atteste.","**Karim** prépare le bac sans être scolarisé dans un lycée : il est candidat individuel."]},{"id":"sacha","type":"tableau","titre":"Les épreuves de Sacha","colonnes":["Activité","Note sur 20"],"lignes":[["Demi-fond","13"],["Badminton","11"],["Natation","Absent, non justifié"]],"source":"Notes écrites pour l’exercice"}],"questions":[{"enonce":"Relie chaque élève à ce que prévoit le règlement.","aide":"Relis chaque situation : absence, blessure attestée, statut de candidat.","type":"association","gauche":[{"id":"g0","texte":"Sacha, absent sans justificatif"},{"id":"g1","texte":"Lola, blessée avec certificat"},{"id":"g2","texte":"Karim, candidat individuel"}],"droite":[{"id":"d0","texte":"Un examen ponctuel sur deux activités"},{"id":"d1","texte":"Une épreuve adaptée ou différée"},{"id":"d2","texte":"Un 0 à cette épreuve, sans élimination"}]},{"enonce":"Quelle est la note finale d’EPS de Sacha, avec 0 à la natation ?","aide":"Fais la moyenne de 13, 11 et 0.","type":"nombre","unite":"/20"},{"enonce":"S’il avait obtenu 12 à la natation, quelle aurait été sa note finale ?","aide":"Fais la moyenne de 13, 11 et 12.","type":"nombre","unite":"/20"},{"enonce":"Lola ne peut pas fournir d’effort physique. L’évaluation peut-elle reposer seulement sur l’AFL2 et l’AFL3 ?","aide":"Pense à la part de l’évaluation qui concerne l’action, même en cas d’inaptitude.","type":"choix","options":[{"id":"a","texte":"Non : il reste toujours une part d’action motrice, adaptée à sa blessure si besoin"},{"id":"b","texte":"Non : elle doit faire l’épreuve normale, sans aucune adaptation"},{"id":"c","texte":"Oui : une blessure supprime définitivement l’évaluation de l’action motrice"},{"id":"d","texte":"Oui : l’AFL1 est un bonus qui ne compte pas dans la note finale"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"Absence non justifiée : **0** à l’épreuve, non éliminatoire. Blessure attestée : épreuve **adaptée ou différée**. Candidat individuel : **examen ponctuel** sur deux activités."},{"cle":{"type":"nombre","valeur":8,"tolerance":0},"affichage":"8 /20","explication":"(13 + 11 + 0) ÷ 3 = 24 ÷ 3 = **8/20**."},{"cle":{"type":"nombre","valeur":12,"tolerance":0},"affichage":"12 /20","explication":"(13 + 11 + 12) ÷ 3 = 36 ÷ 3 = **12/20**. Son absence lui a coûté 4 points."},{"cle":{"type":"choix","ids":["a"]},"explication":"Même en cas d’inaptitude partielle, l’évaluation **ne repose jamais** sur les seuls AFL2 et AFL3 : il y a toujours une part d’action motrice, adaptée si besoin."}]$ex$::jsonb),
