b","texte":"Jade"},{"id":"c","texte":"Tom"},{"id":"d","texte":"Aucun des trois"}],"multiple":false},{"enonce":"Combien d’élèves du tableau ne respectent pas cette règle ?","aide":"Cherche ceux qui ont deux activités du même champ.","type":"nombre"},{"enonce":"Touche les deux activités de Jade qui relèvent du même champ.","aide":"Pense aux activités où l’on présente une prestation jugée.","type":"zone","document":"trio","multiple":true}]}$ex$::jsonb,
