   $ex${"titre":"Six essais en longueur","competence":"analyser-document","situation":"Jules passe son épreuve de saut en longueur. Son professeur lui donne six essais. La performance est notée sur 6 points d’après un barème de l’établissement, à partir de sa meilleure distance valide.","documents":[{"id":"essais","type":"tableau","titre":"Les six essais de Jules","colonnes":["Essai","Distance (m)"],"lignes":[["1","4,35"],["2","4,62"],["3","Nul"],["4","4,78"],["5","4,70"],["6","4,95"]],"source":"Résultats écrits pour l’exercice"},{"id":"bareme","type":"tableau","titre":"Barème de performance","colonnes":["Distance minimale (m)","Points sur 6"],"lignes":[["3,60","2"],["4,00","3"],["4,50","4"],["4,90","5"],["5,30","6"]],"source":"Barème écrit pour l’exercice"}],"questions":[{"enonce":"Quelle est la meilleure performance de Jules, en mètres ?","aide":"Cherche la plus grande distance valide.","type":"nombre","unite":"m"},{"enonce":"Combien de points sur 6 cette distance lui rapporte-t-elle ?","aide":"Cherche le plus grand seuil que 4,95 m atteint.","type":"nombre","unite":"points"},{"enonce":"Combien de centimètres lui manque-t-il pour atteindre le palier de 6 points ?","aide":"Soustrais sa distance à 5,30 m, puis convertis en centimètres.","type":"nombre","unite":"cm"},{"enonce":"Touche le numéro de l’essai nul.","aide":"Cherche le mot « Nul » et regarde la ligne.","type":"zone","document":"essais","multiple":false},{"enonce":"Après son essai nul, que doit décider Jules au quatrième essai ?","aide":"Pense à la vitesse utile et à la stratégie d’essais.","type":"choix","options":[{"id":"a","texte":"Sauter sans course d’élan pour être certain de ne pas dépasser la planche"},{"id":"b","texte":"Arrêter de sauter pour ne pas se fatiguer avant la fin de l’épreuve"},{"id":"c","texte":"Assurer un essai valable en réglant son élan, avant de retenter plus loin"},{"id":"d","texte":"Courir à la vitesse maximale, même si le geste se désorganise totalement"}],"multiple":false}]}$ex$: