   $ex${"titre":"Lire la carte de la forêt","competence":"lire-carte","situation":"Pour sa première course d’orientation, Emma étudie l’extrait de carte du parcours. Elle doit d’abord comprendre la légende, puis repérer ce qui peut l’aider à ne pas se perdre.","documents":[{"id":"carte","type":"schema","titre":"Extrait de carte d’orientation","largeur":340,"hauteur":220,"elements":[{"forme":"rect","x":20,"y":20,"l":300,"h":176,"teinte":"blanc","motif":"plein"},{"forme":"rect","x":110,"y":36,"l":100,"h":90,"teinte":"vert","motif":"hachures","id":"z1","zone":true},{"forme":"ellipse","cx":268,"cy":76,"rx":40,"ry":28,"teinte":"bleu","motif":"plein","id":"z2","zone":true},{"forme":"rect","x":34,"y":120,"l":70,"h":50,"arrondi":8,"teinte":"jaune","motif":"clair","id":"z3","zone":true},{"forme":"polygone","points":[[128,172],[168,140],[210,172]],"teinte":"brun","motif":"clair","id":"z4","zone":true},{"forme":"rect","x":20,"y":184,"l":300,"h":8,"teinte":"encre","motif":"plein","id":"z5","zone":true}]},{"id":"legende","type":"tableau","titre":"Légende","colonnes":["Couleur","Signification"],"lignes":[["Jaune","Zone découverte"],["Blanc","Forêt facile à traverser"],["Vert","Végétation plus dense"],["Bleu","Eau"],["Marron","Relief"],["Trait noir","Chemin"]],"source":"D’après la légende usuelle des cartes d’orientation"}],"questions":[{"enonce":"Touche la zone de végétation dense.","aide":"Relis la légende pour trouver la couleur de la végétation dense.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche la zone découverte.","aide":"Cherche la couleur qui signifie « zone découverte ».","type":"zone","document":"carte","multiple":false},{"enonce":"Touche l’élément linéaire qui peut servir de ligne directrice.","aide":"Une ligne directrice se suit sur la longueur, sans se perdre.","type":"zone","document":"carte","multiple":false},{"enonce":"Le nord de la carte est en haut de la feuille, mais la boussole indique le nord derrière Emma. Que doit-elle faire ?","aide":"Il s’agit d’orienter la carte.","type":"choix","options":[{"id":"a","texte":"Tourner la carte jusqu’à ce que son nord coïncide avec le nord de la boussole"},{"id":"b","texte":"Garder la carte telle quelle, car le nord de la boussole n’a pas d’importance"},{"id":"c","texte":"Plier la carte pour que seule la zone découverte reste visible"},{"id":"d","texte":"Retourner la carte sens dessus dessous pour que le sud soit en haut"}],"multiple":false}]}$ex$::jsonb,
