   $ex${"titre":"Trois postes, deux itinéraires","competence":"raisonner","situation":"Sur un parcours, Lucas doit rejoindre trois postes. Entre chacun, il peut couper en ligne droite par la forêt dense ou passer par le chemin, plus long. Il compare les deux choix avant de partir.","documents":[{"id":"parcours","type":"schema","titre":"Le parcours (schéma non à l’échelle)","largeur":340,"hauteur":220,"elements":[{"forme":"rect","x":90,"y":60,"l":130,"h":100,"teinte":"vert","motif":"hachures"},{"forme":"chemin","d":"M 50 180 L 50 40 L 290 40 L 290 180","teinte":"encre"},{"forme":"cercle","cx":50,"cy":180,"r":13,"texte":"1","teinte":"violet","motif":"clair"},{"forme":"cercle","cx":50,"cy":40,"r":13,"texte":"2","teinte":"violet","motif":"clair"},{"forme":"cercle","cx":290,"cy":180,"r":13,"texte":"3","teinte":"violet","motif":"clair"},{"forme":"ellipse","cx":140,"cy":190,"rx":30,"ry":15,"teinte":"bleu","motif":"plein","id":"z1","zone":true},{"forme":"cercle","cx":250,"cy":150,"r":9,"teinte":"brun","motif":"plein","id":"z2","zone":true},{"forme":"texte","x":250,"y":128,"texte":"Rocher","taille":"petit","ancre":"milieu"},{"forme":"texte","x":140,"y":212,"texte":"Étang","taille":"petit","ancre":"milieu"}]},{"id":"temps","type":"tableau","titre":"Les deux choix","colonnes":["Étape","Trajet direct, en forêt dense","Trajet par le chemin"],"lignes":[["Poste 1 → poste 2","240 m à 40 m/min","400 m à 100 m/min"],["Poste 2 → poste 3","200 m à 40 m/min","350 m à 100 m/min"]],"enteteLignes":true,"source":"Vitesses écrites pour l’exercice"}],"questions":[{"enonce":"Combien de minutes dure le trajet direct du poste 1 au poste 2 ?","aide":"Temps = distance ÷ vitesse : 240 ÷ 40.","type":"nombre","unite":"min"},{"enonce":"Et le trajet par le chemin, du poste 1 au poste 2 ?","aide":"Même calcul avec 400 m et 100 m/min.","type":"nombre","unite":"min"},{"enonce":"Sur les deux étapes, combien de minutes le chemin fait-il gagner par rapport aux trajets directs ?","aide":"Direct : 6 + 5. Chemin : 4 + 3,5.","type":"nombre","unite":"min"},{"enonce":"Le poste 3 est dans la forêt. Touche l’élément facile à trouver près de lui, d’où Lucas finira avec précision.","aide":"Cherche un repère proche du poste 3, pas l’étang.","type":"zone","document":"parcours","multiple":false},{"enonce":"Pourquoi un trajet plus long par le chemin peut-il être le meilleur choix ?","aide":"Compare la vitesse de déplacement dans les deux milieux.","type":"choix","options":[{"id":"a","texte":"On y avance bien plus vite et on risque moins de perdre la direction"},{"id":"b","texte":"Les postes se trouvent toujours sur les chemins, jamais dans la forêt"},{"id":"c","texte":"Le chemin est toujours plus court que la ligne droite, quelle que soit la carte"},{"id":"d","texte":"La traversée de la forêt dense est interdite par le règlement de l’épreuve"}],"multiple":false}]}$ex$::jsonb,
