   $ex${"titre":"La phrase dansée","competence":"lire-tableau","situation":"Quatre danseurs composent une phrase chorégraphique en quatre temps. Chaque temps utilise un procédé de composition différent. Le plan de la chorégraphie est noté dans un tableau.","documents":[{"id":"plan","type":"tableau","titre":"Le plan de la chorégraphie","colonnes":["Temps","Durée","Ce que font les quatre danseurs"],"lignes":[["Temps 1","8 s","Les quatre lèvent le bras au même moment"],["Temps 2","12 s","Chacun reprend le même geste, un peu après son voisin"],["Temps 3","6 s","Un mouvement très lent, puis un mouvement très rapide"],["Temps 4","10 s","À chaque reprise, un nouveau geste s’ajoute à la phrase"]],"source":"Plan écrit pour l’exercice"}],"questions":[{"enonce":"Relie chaque temps au procédé de composition utilisé.","aide":"Unisson : ensemble. Canon : décalé. Contraste : opposé. Accumulation : qui s’ajoute.","type":"association","gauche":[{"id":"g0","texte":"Temps 1"},{"id":"g1","texte":"Temps 2"},{"id":"g2","texte":"Temps 3"},{"id":"g3","texte":"Temps 4"}],"droite":[{"id":"d0","texte":"Contraste"},{"id":"d1","texte":"Accumulation"},{"id":"d2","texte":"Canon"},{"id":"d3","texte":"Unisson"}]},{"enonce":"Quelle est la durée totale de la phrase chorégraphique, en secondes ?","aide":"Additionne les quatre durées.","type":"nombre","unite":"s"},{"enonce":"Touche la durée du temps le plus long.","aide":"Compare les quatre durées.","type":"zone","document":"plan","multiple":false}]}$ex$::jsonb,
